window.X2=window.X2||{};window.X2.chapters=[{"id":"ch1","num":"第一章","title":"相遇","short":"相遇","badge":"1","color":"cc-bg1","summary":"序章性质的章节：一边熟悉阿伐利缇亚商会，一边把战斗系统的基本功（走A、取消攻击）练熟。","place":["阿伐利缇亚商会","格尔特蒙特","涡潮号","古代船"],"keypoints":[{"text":"本章最重要的三件事：解锁「收纳包」并给全队塞上甜品、把**走A**和**取消攻击**练熟、别漏掉古代船里的一次性宝箱。","kind":"warn","title":"本章优先级"},{"text":"没有血药、蓝药的概念：回血只能靠异刃武技/必杀技，收纳包道具（增益料理）是战斗核心之一，甜品普遍加武技填充速度，很实用。","kind":"tip","title":"关于回复"}],"steps":[{"title":"去找阿伐利缇亚商会[[地标:中央交易所]]柜台前的梅洛洛对话","body":"跟爷爷旁边的海拉姆对话，支付 15G —— 以后异刃时叶的牵绊环解锁会方便些。","notes":[{"text":"系统更新：菜单「传送」解锁。","kind":"tip","title":null}]},{"title":"穿过阿伐利缇亚市场，前往阁楼的商会会长室","body":"对话后 100000G 入手（寄钱回老家）。","notes":[{"text":"谈完生意、寄钱回老家后，先去睡个「保健觉」，再逛逛集市。除了主线要求的鱼店，**[[物品:蜂蜜糖浆]]甜品店**出售的「[[物品:纳西梨果冻]]」是当前最好用的收纳道具，能极快提升战斗中武技恢复速度；预算不够时买「[[物品:亮晶晶砂糖]]」也行。","kind":"tip","title":"商会逛法"}]},{"title":"回到[[地标:格尔特蒙特返航港]]，向爷爷报告","body":"","notes":[{"text":"系统更新：菜单「任务日志」解锁。","kind":"tip","title":null}]},{"title":"完成「[[任务:重要工作之前]]」","body":"","notes":[]},{"title":"在阿伐利缇亚商会 3 楼的[[地标:莱姆莱伊姆旅店]]稍事休息","body":"[[地标:莱姆莱伊姆旅店]]选择「稍作休憩」90G。","notes":[{"text":"系统更新：「住宿设施」开启；旅馆内可用奖励 EXP 提升等级（奖励 EXP 来自完成任务、发现地标）。支线解锁：「[[任务:捉迷藏]]」「[[任务:护送货物]]」。","kind":"tip","title":null},{"text":"此时已经可以接支线了。推荐先接**「[[任务:捉迷藏]]」**：做完能拿一个加力量的道具，顺路熟悉地图和商会里能开的宝箱，攒点零用钱。","kind":"tip","title":"推荐先做"}]},{"title":"按照巴恩会长的指示，前往[[地标:格尔特蒙特]]出发港","body":"","notes":[{"text":"系统更新：菜单「收纳包设置」解锁；交易/情报/生活/打捞/饰品商店开启。支线解锁：「[[任务:第1000次迟到]]」。","kind":"tip","title":null},{"text":"商店与收纳包系统解锁后，优先把甜品塞进 3 个角色（莱克斯、尼娅、灭）的收纳包。","kind":"tip","title":null}]},{"title":"探索涡潮号，并与委托人们对话","body":"分别与尼娅、白虎、真、灭、斩铁对话。","notes":[]},{"title":"登上甲板，找了望台上的莫奈尔对话","body":"选择换班。","notes":[]},{"title":"下楼梯，赶往集合地点","body":"第三个房间有个宝箱，内有急速时钟和 400 多 G —— 下楼梯后就没法回来拿了。","notes":[{"text":"剧情后尼娅、灭、真入队；系统更新：菜单「队伍编成」解锁。**真和灭非常强**，建议编成让他们打，主角在旁边看戏就行。","kind":"tip","title":null}]},{"title":"前往古代船的入口","body":"身后就有一个宝箱，顺便拿了。","notes":[]},{"title":"打倒王者海蟑螂","body":"战斗：Lv2 王者海蟑螂。","notes":[]},{"title":"探索古代船内部（练习战斗基本功）","body":"古代船内宝箱不少，可以一边探索一边练战斗技巧。","notes":[{"text":"**走A**：在第一段自动攻击打中对手的瞬间，轻推左摇杆让角色轻微移位，取消掉后续 2 段自动攻击，只反复打出第 1 段。目的不是提高单次伤害，而是提高自动攻击频率，快速回复武技槽。","kind":"tip","title":"技巧 1：走A"},{"text":"**取消攻击**：在上一个攻击动作结束的瞬间按下武技/必杀技，会取消后续动作并出现蓝色光圈，伤害与槽的回复都更高。游戏内教学讲得不好懂，实际就是「动作收招瞬间按键」。主角专用剑自动攻击只有一段，武技快填满时不停按就能稳定触发。","kind":"tip","title":"技巧 2：取消攻击"},{"text":"古代船剧情结束后**无法再回来**，尽量把宝箱收干净。","kind":"warn","title":null}]},{"title":"前往第一燃料库取得以太动力缸，回去调查系统控制室的以太燃料口，打开大门","body":"开启大门后迎战 Boss。","notes":[]},{"title":"打倒巨刃海豚蜥","body":"战斗：Lv4 巨刃海豚蜥。","notes":[{"text":"敌人攻击力相当高，愤怒后可以秒掉主角，而且不少是范围攻击。让主角跑远，交给真和灭收拾。","kind":"tip","title":null}]},{"title":"去山丘上的少女身旁","body":"","notes":[]},{"title":"打倒灭","body":"战斗：Lv5 灭。这是必杀技与异刃连击的教学战。","notes":[{"text":"这场单挑对砍本质上比的是主角自身面板（等级、饰品、收纳料理、牵绊环），只要不开极难都能打过；唯一真正用得上的技巧就是攻击取消。","kind":"tip","title":null}]}],"diffs":[{"src":"《攻略特辑》（掌机王Plus）","text":"「[[物品:银河魔方]]」（自动攻击命中时有 50% 概率发生 2 次攻击）与打捞员等级挂钩：打捞员等级最低 5 级、最高 1 级，在[[地标:格尔特蒙特飞行甲板]]与 NPC 莫奇莫奇对话、支付报酬即可查看当前等级，每次晋升都有报酬；打捞次数超过 100 次即可达到 1 级。配上焰/光的圣杯之剑效果极好，属于能用到通关后期的强力装备。"},{"src":"《攻略特辑》（掌机王Plus）","text":"《攻略特辑》在本章顺带给了键位表与「稀有核心水晶刷起来」的抽卡说明：本作在单机里放了抽卡要素且自动保存，出货率不友好，前期建议「勤能补拙」慢慢攒。本站把完整键位表放在「系统与养成 → 新手入门」中。"}],"quests":["捉迷藏","护送货物","第1000次迟到","重要工作之前"],"images":[{"src":"assets/mag/vol1-p002.webp","alt":"上册 第 2 页：初心者入门指南与键位操作表","caption":"初心者入门指南与键位操作表","src_ref":"原刊：上册 第 2 页（《掌机王Plus 异度神剑2 攻略特辑》）","link":"#/mag/vol1-002"},{"src":"assets/mag/vol1-p003.webp","alt":"上册 第 3 页：刷核心水晶 / 角甲兽千万别打死 / 战斗系统入门","caption":"刷核心水晶 / 角甲兽千万别打死 / 战斗系统入门","src_ref":"原刊：上册 第 3 页（《掌机王Plus 异度神剑2 攻略特辑》）","link":"#/mag/vol1-003"},{"src":"assets/mag/vol1-p012.webp","alt":"上册 第 12 页：第 1 章流程：商会 → 古代船","caption":"第 1 章流程：商会 → 古代船","src_ref":"原刊：上册 第 12 页（《掌机王Plus 异度神剑2 攻略特辑》）","link":"#/mag/vol1-012"}]},{"id":"ch2","num":"第二章","title":"机械人偶","short":"机械人偶","badge":"2","color":"cc-bg2","summary":"古拉篇：开启牵绊圆环、异刃连击、TigerTiger 与稀有异刃调谐，是真正开始「养成」的一章。","place":["古拉","托里格镇","巨神兽战舰"],"keypoints":[{"text":"本章两条主线：一是**牵绊圆环**（优先学「武技取消武技」），二是**异刃连击**的属性路线。","kind":"warn","title":"本章优先级"},{"text":"古拉牧场那只头上有感叹号的 1 级幼生鳞甲兽**千万别杀**——那是喂食支线，养成后回报丰厚，杀了还存档就只能二周目了。","kind":"warn","title":"不要手贱"},{"text":"留人原则：场景技能好的「黑叔叔/黑阿姨」（普通异刃）比稀有异刃更实用、更好养活，前期异刃槽紧张时它们才是主力。","kind":"tip","title":"关于普通异刃"}],"steps":[{"title":"搜索森林并找到爷爷","body":"","notes":[{"text":"系统更新：核心晶片商店开启；菜单「异刃设置」「武器强化」「牵绊圆环」解锁。","kind":"tip","title":null},{"text":"此处有个宝箱，内有[[物品:飞翼晶片]]，目前很强力，直接给焰强化。","kind":"tip","title":null}]},{"title":"继续前往森林深处，找到尼娅和白虎","body":"继续前进会有采集系统与场景技能系统的教学。","notes":[]},{"title":"打倒食虫巨蛙","body":"战斗：Lv6 食虫巨蛙。战后尼娅和白虎加入队伍。","notes":[]},{"title":"穿过森林，向古拉领的城镇进发","body":"古拉・下层地图尽头两侧的宝箱各有一个[[物品:獠牙晶片]]。","notes":[]},{"title":"前往古拉最大的城镇托里格","body":"进入格尔德亚大平原后笔直往东。","notes":[{"text":"系统更新：菜单「跳过时间」解锁。支线解锁：「[[任务:遭受袭击的诺彭商人]]」。","kind":"tip","title":null},{"text":"不远处就是第一个冠名者「[[敌人:孤高的巴巴里]]」，目前打不过，无视他。","kind":"tip","title":null},{"text":"途中会经过晚风草原，遇到「[[敌人:赚小零花的洛特]]」——两人就能击败它。","kind":"tip","title":null}]},{"title":"打倒帝国军的士兵们 0/3","body":"战斗：Lv6 斯佩比亚士兵 ×3、Lv8 帕克斯警卫队长。","notes":[{"text":"多目标战，优先打等级低血少的。切换目标的方式是按住 R 键再按 Y/A 左右切换。","kind":"tip","title":null}]},{"title":"打倒[[异刃:迦具土]]和斯佩比亚帝国军士兵 0/2","body":"战斗：Lv8 帕克斯警卫队长、Lv10 [[异刃:迦具土]]。优先攻击帕克斯警卫队长。战后尼娅和白虎离队。","notes":[]},{"title":"直接前往虎的家避难","body":"","notes":[]},{"title":"调查虎家里的厨房，让焰做些料理","body":"获得 热带芋 ×2、绚丽南瓜 ×3、激热橙 ×5、油牡蛎 ×1、肉味辣椒 ×1。调查厨房制作「猎人风煮热带芋」。","notes":[]},{"title":"完成「[[任务:尼娅的情报收集]]」","body":"","notes":[{"text":"支线解锁：「[[任务:鲜艳的水果馅饼]]」「[[任务:托里格的起重机破坏事件]]」。","kind":"tip","title":null},{"text":"托里格商店街会触发剧情事件，获得无名的核心水晶并强制调谐，**必定是风属性拳套回复异刃**（技能随机），这是唯一一次不强制存档的调谐。","kind":"tip","title":"强制调谐"},{"text":"系统更新：菜单「异刃绑定」「异刃管理」「辅助核心」解锁，异刃绑定 MAX 提升至 2，辅助核心商店开启。记得把刚调谐的异刃绑给莱克斯。","kind":"tip","title":null}]},{"title":"为购买人造异刃的零件，前往[[地标:托里格镇]]的玛吉杂货店","body":"","notes":[{"text":"支线解锁：「[[任务:不会游泳的少年]]」「[[任务:家具工匠的烦恼]]」「[[任务:善有善报]]」。","kind":"tip","title":null}]},{"title":"达成「[[任务:获得完美测距传感器]]」与「[[任务:获得转轮连接器]]」","body":"","notes":[]},{"title":"回到虎家里完成人造异刃","body":"玩一次 TIGER! TIGER!，虎和花加入。","notes":[]},{"title":"从[[地标:托里格镇]]的加雷古洛之丘前往能眺望巨神兽战舰的地方","body":"","notes":[{"text":"系统更新：菜单「花的定制」「零件制造」「零件结晶化」解锁。给虎装备饰品（前期优先血量），用核心晶片给花强化武器；把「坚坚盾牌」拖进武技栏能大幅提升坦克硬度。","kind":"tip","title":null}]},{"title":"从加雷古洛之丘沿大树根部，从运输口侵入巨神兽战舰内部","body":"","notes":[]},{"title":"救出被关押的尼娅与白虎","body":"使用场景技能破坏通气孔找到白虎；白虎所在房间内有宝箱，其他牢房被锁住暂时打不开。机关室关闭锅炉解除蒸汽。","notes":[]},{"title":"打倒看守尼娅牢房的帝国军士兵们","body":"战斗：Lv11 斯佩比亚士兵、Lv12 斯佩比亚中士。","notes":[{"text":"优先攻击等级低的，干掉一个后我方压力小很多；多使用异刃切换——切换异刃后武技会直接填充满。战后尼娅和白虎归队，获得第 1 防卫隔离壁钥匙。","kind":"tip","title":null}]},{"title":"逃离巨神兽战舰","body":"打开整备室的门到兵器整备室，机库门打不开，电源开关在上层，只能绕路。取走兵器整备室角落的第 2 防卫隔离壁钥匙，用它打开西边防卫门。","notes":[{"text":"出现本作第一个牵绊对话「斯佩比亚的技术」。牵绊对话中选项不同，奖励也不同。","kind":"tip","title":"牵绊对话"}]},{"title":"打倒莫夫","body":"战斗：Lv13 莫夫。80% 出剧情然后继续殴打他，可以趁此练习异刃连击。","notes":[{"text":"推荐连击路线：火(焰)-水(白虎)-火(焰)；水(白虎)-地(花)-风(初始黑人)；地(花)-火(焰)-地(花)。战后获得收纳包扩张工具。","kind":"tip","title":"异刃连击路线"}]},{"title":"穿过斯佩比亚军托里格基地，逃到[[地标:托里格镇]]外面","body":"","notes":[]},{"title":"打倒梅勒芙","body":"战斗：Lv15 梅勒芙。双方都在放水的战斗。","notes":[]},{"title":"古拉地图支线与收集（可自由安排）","body":"本章古拉可做的事很多，建议按下面的清单顺手清理。","notes":[{"text":"① 在古拉镇门口杀死 8 级珍稀种怪物「[[敌人:赚小零花的洛特]]」，可获得 [[物品:兔怪项圈◆◆◆]]与辅助核心[[物品:牵绊攻击 1]]。","kind":"tip","title":"古拉清单"},{"text":"② 完成支线「崔娜的食谱」（可选），完成可增加焰的料理种类。另有「[[任务:善有善报]]」，是教学性质支线，初步接触并拿到商店店契；「[[任务:长不大的蔬菜]]」（可选）有后续。","kind":"tip","title":null},{"text":"③ 处理好毒池后，毒池里有个白金宝箱；毒池往前走一点可开启「[[地标:托德里格花田]]」地标。在古拉情报商处可购买食谱「[[物品:托德里烤肉食谱]]」，增加焰的料理种类，同时是莱克斯喜欢的收纳道具。","kind":"tip","title":null},{"text":"④ BOSS 战后从古拉小镇逃离会到达地标「[[地标:旅行者休息树]]」，其正北方向很近就是古拉重要地标「[[地标:伐木场]]」，建议先开启再接主线。","kind":"tip","title":null},{"text":"⑤ BOSS 战后在旅馆睡一觉，在云海落潮状态下前往「[[地标:下沉遗忘封地]]」读取牵绊对话。","kind":"tip","title":null},{"text":"⑥ 主线船厂任务寻回逃离的巨神兽时，喂食巨神兽后别急着离开：趁着云海涨潮往前游一点，不远处有 2 个宝箱。","kind":"tip","title":null},{"text":"⑦ 古拉牧场那只头上有感叹号的 1 级幼生鳞甲兽是喂食支线，养成后有丰厚回报，**千万别杀，更别杀了再存档**。","kind":"warn","title":null},{"text":"⑧ 传送「[[地标:旅行者休息树]]」，回身往后走跳下去可达「[[地标:暴龙的巢穴]]」，里面有白金宝箱。","kind":"tip","title":null}]},{"title":"系统与养成要点（本章集中讲解）","body":"第二章是系统集中解锁的一章，下面这几块内容建议一次看懂。","notes":[{"text":"**牵绊圆环（御刃者）**：就是御刃者的技能加点，分内列/外列，内列需二周目开启。最内环学会 2 个技能解锁第二环，第二环再学 2 个解锁最外第 3 环。前期最重要的是**优先学「武技取消武技」**，这是本作的分水岭；直接加属性的技能性价比很低，除非是解锁下一环的前置，不要优先点。","kind":"tip","title":"牵绊圆环"},{"text":"推荐学习顺序 —— 莱克斯：高速反应 → 速攻1 → 武技连锁（分水岭）→ 学习以太 → 速攻2 → 肌肉锻炼 → 健康优良儿 → 速攻3 → 强化连击 → 连携的极致 → 倒地高手，剩下随意。尼娅：以太的才能 → 野性觉醒 → 连抓（分水岭）→ 动态视力 → 野性觉醒2 → 药草调和 → 野性觉醒3 → 治疗者 → 巨猫 → 合气，剩下随意。虎：万全准备1 → 柔韧身躯 → 万全准备2 → 幸运男孩 → 硬撑 → 诺鹏式连续攻击（分水岭）→ 万全准备3 → 安慰剂 → 更柔韧的身躯，剩余随意。","kind":"tip","title":"加点顺序"},{"text":"**异刃牵绊圆环**：左边 3 列红色是异刃 3 段必杀技的效果与名字；中间 3 列黄色相当于被动技能；最右边 3 列绿色是场景技能（地图技能）。从里到外共 5 层，一列对应 1 个技能。异刃解锁更高级的关键牵绊奖励大多需要友好度（牵绊值）或做支线任务，或两者都要；即使解锁了关键牵绊奖励，环内技能没点亮也不算激活，遇到「???」说明当前主线进度未达标。","kind":"tip","title":null},{"text":"**异刃连击**：异刃共 8 种属性——火、水、风、冰、土、电、光、暗，其中火水互克、风冰互克、土电互克、光暗互克。必杀技分 3 段，屏幕右下角最右边是必杀槽，罗马数字代表当前段数。释放 1 级必杀后，在上方连击走条结束前接属性相配的 2 级必杀，再在新走条结束前接 3 级必杀，即可打出动画与高伤害。完成 3 段连击后，敌人会获得一个与第 3 段属性对应的抗性球，再用同属性攻击伤害会下降，所以尽量多换路线。","kind":"tip","title":"异刃连击"},{"text":"**TigerTiger**：共 5 个关卡，新关卡靠主线进度解锁，进度越靠后可获得的道具越好。START 是正常模式，END 是简单模式（简单模式撞墙没有伤害）。不同关卡产出的零件不同，按需要刷即可。","kind":"tip","title":"TigerTiger"},{"text":"**初期异刃抽取**：抽到的普通异刃别无脑扔，前期主要留场景技能好的——打捞技术、植物学、森林学、昆虫学、农学、生成技术、矿物学、鱼类学、远征等；自带属性之力、有 3 个场景技能且其中 2 个能升到 3 级的就很不错。莱克斯前期不建议多抽，留 1~2 个能用的即可，高级核心优先给尼娅。优先找 3 级打捞技术的普通异刃并把打捞技术升起来；第 4 章之前，莱克斯建议配一个风属性异刃，尼娅配冰、土、电比较理想。","kind":"tip","title":"抽卡策略"},{"text":"**花的电路板**：花是人造异刃，可高度自定义。能量转换器＝电池，装零件会消耗电池功耗，零件越高级功耗越高，功耗不够就用以太结晶升级电池；战斗类别＝属性修正（生命、灵巧、力量、以太力、敏捷、运气），插什么零件就加什么，最高 25%；武技卡＝异刃武技追加效果；技能 RAM＝辅助核心插槽；必杀技强化 RAM＝必杀技追加效果；扩张技能＝辅助核心扩充插槽。","kind":"tip","title":"花的定制"},{"text":"**异刃友好度**的主要三种获取途径：①完成任务（主线/支线）；②往收纳包填普通收纳道具；③往收纳包填[[物品:迷恋药]]（1 次 3000 好感，DLC 限定）。没买 DLC 想轻松提升好感基本无解，只能反复填道具（一次 10 多点）；买了 DLC 前期直接送 10 瓶[[物品:迷恋药]]，中后期可接任务自制。","kind":"tip","title":"友好度"}]}],"diffs":[{"src":"《攻略特辑》（掌机王Plus）","text":"《攻略特辑》把「异刃连击 → 属性球 → 连锁攻击」讲得更细：对敌人打出一整套异刃连击后会附加与第 3 段必杀同属性的「属性球」，每种属性只能挂 1 个，最多同时挂 8 个；属性球只能在连锁攻击中击破，相克属性两次即可击破、非相克需 3 次，每击破一个就多获得一轮连锁并提高伤害倍率。第 8 章后焰/光可解锁觉醒模式，觉醒状态下参与连锁对**所有**属性球都能造成伤害，因此进连锁前先让焰/光进入觉醒状态。连锁中敌人 HP 归零仍可继续攻击（Overkill），会额外奖励 2 倍以上经验与更多掉落。"},{"src":"《每章更多备注》","text":"备注版补了连锁的细节：小队槽攒满 1 段可复活倒下的同伴，攒满 3 段按 + 发动连锁；一轮连锁中若一个属性球都没破，连锁立刻结束；破掉全部属性球会追加一轮。异刃每次出手后进入冷却，若本轮攻击打到属性球则回复一半冷却，下一轮按键挑战成功再回复另一半，所以队伍属性搭配要提前算好克制关系。备注还提醒：把整个战斗系统当主要输出手段之前，先老老实实把异刃连击与连锁练熟。"}],"quests":["遭受袭击的诺彭商人","尼娅的情报收集","鲜艳的水果馅饼","托里格的起重机破坏事件","不会游泳的少年","家具工匠的烦恼","善有善报","获得完美测距传感器","获得转轮连接器","长不大的蔬菜"],"images":[{"src":"assets/mag/vol1-p006.webp","alt":"上册 第 6 页：异刃系统：种类、位阶效果、心相","caption":"异刃系统：种类、位阶效果、心相","src_ref":"原刊：上册 第 6 页（《掌机王Plus 异度神剑2 攻略特辑》）","link":"#/mag/vol1-006"},{"src":"assets/mag/vol1-p007.webp","alt":"上册 第 7 页：场景技能 / 异刃去留 / 破球者与产球者","caption":"场景技能 / 异刃去留 / 破球者与产球者","src_ref":"原刊：上册 第 7 页（《掌机王Plus 异度神剑2 攻略特辑》）","link":"#/mag/vol1-007"},{"src":"assets/mag/vol1-p011.webp","alt":"上册 第 11 页：迷你游戏《TIGER! TIGER!》","caption":"迷你游戏《TIGER! TIGER!》","src_ref":"原刊：上册 第 11 页（《掌机王Plus 异度神剑2 攻略特辑》）","link":"#/mag/vol1-011"},{"src":"assets/mag/vol1-p013.webp","alt":"上册 第 13 页：第 2 章流程与宝箱","caption":"第 2 章流程与宝箱","src_ref":"原刊：上册 第 13 页（《掌机王Plus 异度神剑2 攻略特辑》）","link":"#/mag/vol1-013"},{"src":"assets/mag/vol1-p014.webp","alt":"上册 第 14 页：第 2 章流程：巨神兽战舰 / 莫夫 / 梅勒芙","caption":"第 2 章流程：巨神兽战舰 / 莫夫 / 梅勒芙","src_ref":"原刊：上册 第 14 页（《掌机王Plus 异度神剑2 攻略特辑》）","link":"#/mag/vol1-014"}]},{"id":"ch3","num":"第三章","title":"战争","short":"战争","badge":"3","color":"cc-bg3","summary":"英维迪亚篇：佣兵团系统开放、御刃者连击（素质四连）教学、DLC 与必做支线集中出现。","place":["英维迪亚","乌摩恩造船厂","弗雷斯贝古村","冯斯麦姆"],"keypoints":[{"text":"本章必做：**拿到花的制作书**（[[地标:下颚漂流地]]第 3 章开头着陆点边上的箱子，获得「手巧的诺彭惹人爱」）、**拿第二个超频**（佣兵村宝箱）、尽量做掉 DLC 支线拿[[物品:磁力晶片]]。","kind":"warn","title":"本章必做"},{"text":"BOSS 战（灭与义经）是主线第一场硬仗：目标是**把义经打到 50% 触发剧情**，别硬啃灭。","kind":"tip","title":null}],"steps":[{"title":"穿越脊椎骨的界限，前往古拉后方的[[地标:乌摩恩造船厂]]","body":"笔直往北走来到古拉的左半身。","notes":[{"text":"部分旅馆解锁「好好休息」选项，休息后该处云海高度会变化。","kind":"tip","title":null},{"text":"支线解锁：「[[任务:飞向憧憬的天空]]」「[[任务:长不大的蔬菜]]」「[[任务:少年的倔强]]」「[[任务:抛弃故乡]]」。左半身地图较简单，中途有冠名者「[[敌人:狙击的格斯]]」，被它发现就直接跑。","kind":"tip","title":null}]},{"title":"完成「[[任务:乌摩恩的船]]」","body":"","notes":[]},{"title":"去找乌摩恩对话，出发前往[[地标:世界树]]","body":"","notes":[]},{"title":"向位于英维迪亚背部的城镇进发","body":"系统更新：TIGER! TIGER! 追加新关卡。支线解锁：「[[任务:神秘便笺]]」（在英维迪亚・头部酸液食管捡到「笔记的残片」后触发，没有固定 NPC 接取点）。","notes":[{"text":"本章开头在**英维迪亚烈头部・[[地标:下颚漂流地]]**着陆点边上的箱子里可以拿到**花的制作书**（「手巧的诺彭惹人爱」），这是必须拿的零件制作书。","kind":"tip","title":"花的制作书"},{"text":"同一区域毒池处可获得神秘便签，开启大型系列支线**「诺彭族历史」**系列（很坑很长，可后面慢慢做）。","kind":"tip","title":null},{"text":"毒池处可通往**[[地标:龙之气管]]**，那里有 2 只蜜罐兽，概率掉落 [[物品:巨炮附件◆◆◆]]（后期也能用的毕业级装备之一）；小心其中的精英蜜罐兽。现阶段用不上，可以以后再来刷。","kind":"tip","title":null},{"text":"买了 DLC 的话，可以在佣兵村希尔维奥处领取 DLC 追加支线，**强烈推荐做掉**：获得[[物品:磁力晶片]] ×3，是目前能拿到的最好晶片，加暴击率非常优秀，给焰和神八装备。","kind":"tip","title":"DLC 相关"}]},{"title":"打倒企图抢走焰的团伙 0/3","body":"战斗：Lv18 勇、Lv19 周、Lv20 凡达姆。依旧优先集火等级低的。","notes":[]},{"title":"从杰诺巴斯大空洞前往佣兵团的村庄","body":"在[[地标:弗雷斯贝古村]]与卡尔多尼对话，稍事休息；做好准备后去找后门等待的凡达姆。","notes":[{"text":"支线解锁：「[[任务:佣兵团的模仿者]]」。","kind":"tip","title":null},{"text":"到了佣兵村可以在**瓦格尔酒馆**购买焰喜欢的收纳道具「[[物品:塞利奥红茶]]」。","kind":"tip","title":null},{"text":"**佣兵村宝箱**里可拿到**第二个超频**（第一个在古拉镇招募御刃者处的宝箱里，基本不会错过）。超频可以更换异刃的御刃者归属，非常重要的道具。","kind":"tip","title":"必拿道具"},{"text":"买了 DLC 的话，回商会可领取 2 个赠送的核心水晶（传神的核心水晶、庄严的核心水晶），获得两个强力稀有异刃：火花、神八。火花（传神）给尼娅，神八（庄严）直接给莱克斯；领取 NPC 一个在商会 2 楼，一个在返航港，找头上有奖杯图案的诺彭。","kind":"tip","title":null},{"text":"神八开环较特殊：关键牵绊奖励靠友好度开启，之后技能激活**必须做支线任务**才能激活，可在佣兵村出发市场领取神八的技能激活支线；注意在牵绊圆环里看说明接任务。","kind":"tip","title":null}]},{"title":"向英维迪亚・大喷气孔的顶峰进发","body":"凡达姆和朱雀加入队伍。途中碰到以太瘴气，演示了朱雀清除瘴气的能力。","notes":[]},{"title":"打倒狂暴角甲兽","body":"战斗：Lv21 狂暴角甲兽。莱克斯的钩锚发射追加了倒地效果，同时开始御刃者连击的系统教学。","notes":[{"text":"当前可进行的连击：白虎破防 → 焰倒地 → 朱雀浮空。","kind":"tip","title":null}]},{"title":"打倒长老蜘蛛","body":"战斗：Lv22 长老蜘蛛。","notes":[{"text":"对面异刃的终结爆裂是直线范围伤害，注意站位，避免吃到不必要的伤害。","kind":"tip","title":null}]},{"title":"回到弗雷斯贝古的勇气修炼场，打倒义经","body":"战斗：Lv24 义经。连锁攻击系统解锁。","notes":[{"text":"这是连锁攻击的教学战：开场队伍槽就是满的，但**不要急着发动**——再打一次属性不同的异刃连击，连锁破双球可以直接秒杀 Boss。","kind":"tip","title":"连锁教学"}]},{"title":"再次准备，向英维迪亚王都[[地标:冯斯麦姆]]进发","body":"选择出发，凡达姆和朱雀入队；原来村庄东侧挡住通路的石堆不见了。到达青之岸壁时齐格出现。","notes":[]},{"title":"打倒幽界最凶恶的御刃者 齐格・B・极・玄武","body":"战斗：Lv23 齐格。","notes":[{"text":"齐格的武技伤害非常高，虎以外的角色吃一发基本濒死，要控制好仇恨、注意回复、稳扎稳打。1 球连锁大概能打三分之一，掌握血线后用连锁斩杀。","kind":"tip","title":null}]},{"title":"前往英维迪亚王都[[地标:冯斯麦姆]]","body":"","notes":[{"text":"支线解锁：「[[任务:人人最初都是新手]]」（原备注写作「最初人人都是新手」），可以顺路完成。","kind":"tip","title":null},{"text":"在**[[地标:贝尔扎水门]]**使用场景技能（火属性之力 Lv1 + 风属性之力 Lv1）破坏被堵塞的水闸。","kind":"tip","title":null}]},{"title":"打倒蛮横的御刃者","body":"战斗：Lv23 蛮横的御刃者。进入[[地标:冯斯麦姆]]时遭遇的剧情战斗。","notes":[]},{"title":"前往[[地标:巴杰纳剧场]]的团长室，见见凡达姆的老朋友","body":"","notes":[{"text":"支线解锁：「[[任务:鲜艳的颜料]]」。地点在[[地标:冯斯麦姆]]地图左下角的[[地标:巴杰纳剧场]]。","kind":"tip","title":null}]},{"title":"前往佛尔玛雷旅店留宿","body":"免费住宿触发剧情，焰临时离队。","notes":[]},{"title":"赶往大阶梯之上的[[地标:卡拉姆遗迹]]，打倒灭与义经 0/2","body":"战斗：Lv24 义经、Lv26 灭。焰入队。","notes":[{"text":"**主线第一场难度较高的战斗**。不需要打完全部 HP，任意一名敌人 HP 低于 50% 就会触发剧情，所以战术就是对 HP 较少的义经集火。","kind":"warn","title":"打法要点"},{"text":"义经会使用御刃者封锁与异刃封锁，灭会挑衅导致暂时不能切换目标，要注意攻击目标避免打断异刃连击。建议给御刃者装备增加御刃者封锁抗性的饰品（如[[物品:巫女护符]]），给异刃和花 JS 装备增加异刃封锁抗性的辅助核心/技能 RAM，会好打很多。","kind":"tip","title":null},{"text":"灭的必杀「致命驱动」伤害极高，虎以外的角色硬吃就是秒杀，要时刻注意仇恨目标，尤其是异刃连击终结后容易减员。给义经挂 2 球进连锁基本就能达成本战目标。","kind":"tip","title":null},{"text":"备注版补充：可在英维迪亚烈首都饰品店购买[[物品:巫女护符]]；给焰和神八用之前拿到的[[物品:磁力晶片]]（没买 DLC 的话，可在[[地标:湖上八跳石]]主线往首都方向经过的**[[地标:米奈斯阶地]]**击杀精英 BOSS「[[敌人:灵巧的萨基]]」获得[[物品:紫水晶晶片]]）；第二章的收纳包扩张工具给虎用；在商会甜品店买 3 个[[物品:纳西梨果冻]]给主角三人填收纳包，虎可以多填一个紫色甜品。","kind":"tip","title":"战前准备"},{"text":"备注推荐的饰品搭配：莱克斯＝[[物品:巫女护符]] + 加固定血的背心；尼娅＝[[物品:丰饶项链]] + [[物品:巫女护符]]；虎＝[[物品:巫女护符]] + [[物品:深渊背心]]。战斗中逮着义经打，**土-火-土 3 段必杀连击可以封印义经的封锁**，注意灭的挑衅，挑衅结束后记得切回攻击对象。","kind":"tip","title":null}]},{"title":"再次打倒灭与义经，为凡达姆报仇 0/2","body":"战斗：Lv24 义经、Lv26 灭。战后焰、凡达姆和朱雀离队，光入队。","notes":[]},{"title":"英维迪亚腹部与佣兵村的探索要点","body":"第三章地图够大，下列位置值得专门跑一趟。","notes":[{"text":"① **[[地标:湖上八跳石]]**回身往后看有个山洞，可通往佣兵村的小山上（从村里无法直接到达）。记住这个地方，之后有几个支线会用到。","kind":"tip","title":"区域备忘"},{"text":"② 在头部[[地标:净身水池]]获得神秘便签的任务道具后，[[地标:湖上八跳石]]左边的山岩上可以找到该任务的 NPC 并完成支线。","kind":"tip","title":null},{"text":"③ 在[[地标:法凌中央华段群]]可领取支线「[[任务:人人最初都是新手]]」；该支线点左上方不远有棵大树，是英维迪亚烈重要地标**[[地标:罗尼大树]]**。","kind":"tip","title":null},{"text":"④ 支线「[[任务:人人最初都是新手]]」领取点有一条通往上方的路，那是正确的前往首都路线；顺路会看到很多蜥蜴人，最终看到堵住的水池，用场景技能放干水后出现道路。","kind":"tip","title":null},{"text":"⑤ 从萨尔德门出来顺着左边的路一直走可到达重要地标**[[地标:魂之顶]]**，右边则是前往首都。","kind":"tip","title":null},{"text":"⑥ 第三章 BOSS 战之后建议在[[地标:冯斯麦姆]]港诺彭处领取重要支线（内容与找一位学者有关，学者就在第①条说的洞里），完成后可打开**[[地标:龙之胃]]**这个重要地点。顺带一提：[[地标:龙之胃]]也可以从[[地标:湖上八跳石]]左边的山崖直接跳下去顺着任务指引走；在前往[[地标:龙之胃]]的必经路上有个水池可以潜水，能到达秘境**[[地标:龙之须]]**。","kind":"tip","title":null},{"text":"⑦ 在[[地标:法凌中央华段群]]（地标[[地标:罗尼大树]]）可击杀 26 级精英 BOSS「[[敌人:晴天散步的玛德雷斯]]」（食人花），获得加最高固定值运气的饰品；前期有点难打，位置也难找。","kind":"tip","title":null},{"text":"⑧ 关于[[地标:龙之胃]]的方向：从[[地标:湖上八跳石]]出发，朝**大地图北边**走，走到青之岸壁的下方位置贴着墙摸索，会见到一个入口，进去就是卢加大瀑布。","kind":"tip","title":null}]},{"title":"御刃者连击（素质四连）详解","body":"御刃者的部分武技带有反应动作，可在武技强化界面查看说明。","notes":[{"text":"反应动作分为：破防、倒地、浮空、猛击、击退、吹飞。四连顺序是**破防 → 倒地 → 浮空 → 猛击**，在破防生效后、走条结束前按顺序使用下一段反应动作武技即可完成连击。","kind":"tip","title":null},{"text":"游戏前期一般是：尼娅破防，莱克斯自己完成倒地、浮空、猛击（需要到第 4 章）。配置参考——尼娅：白虎（破防）、弹击球类/以太炮系（破防）、拳套类（浮空）；莱克斯：圣杯之剑（倒地）、斧类（浮空）、神八或朱雀（猛击）；虎：花 JS（倒地）、花 JK（猛击）。","kind":"tip","title":"前期配置"},{"text":"备注提醒：前期想流畅刷素质四连「请不要做梦」，老老实实用必杀连锁打人；想刷装备请在 35~40 级之后去古拉军区旁边的打捞点，用普通气瓶全按失败钓寄居蟹刷[[物品:加速护腕◆◆◆]]，为保持体验建议 45 级左右再去。一般刷[[物品:加速护腕◆◆◆]]是去群岛打 39 级精英 BOSS「[[敌人:天伦拳的里奇]]」；古拉花田的打捞点刷寄居蟹也算不错的选择，可以顺便一起刷钱。","kind":"tip","title":"备注补充"}]}],"diffs":[{"src":"《攻略特辑》（掌机王Plus）","text":"《攻略特辑》对御刃者连击的定位说得更明确：「御刃者连击」的目的不在于打出伤害，而在于控场——四段全部命中会让敌人一段时间无法行动，为输出争取机会；全部命中时掉率也会提升。另外把敌人打浮空会掉落中血瓶、使用猛击会掉落大血瓶，在缺少回复技能的战斗里（例如第 7 章）用它可以有效提升存活率。四个效果跟随武器走（如战斧「强力滑行」附带浮空、双镰刀「猛击之翼」带猛击）。"},{"src":"《每章更多备注》","text":"备注版更强调养成节奏：本章配合 DLC 支线、超频道具与神八/火花的培养，优先把「武技取消武技」和连抓这类分水岭技能点亮，后面战斗会轻松很多。"}],"quests":["飞向憧憬的天空","长不大的蔬菜","少年的倔强","抛弃故乡","乌摩恩的船","神秘便笺","佣兵团的模仿者","人人最初都是新手","鲜艳的颜料"],"images":[{"src":"assets/mag/vol1-p015.webp","alt":"上册 第 15 页：第 3 章流程与英维迪亚腹部地图","caption":"第 3 章流程与英维迪亚腹部地图","src_ref":"原刊：上册 第 15 页（《掌机王Plus 异度神剑2 攻略特辑》）","link":"#/mag/vol1-015"},{"src":"assets/mag/vol1-p018.webp","alt":"上册 第 18 页：英维迪亚支线：佣兵团的模仿者","caption":"英维迪亚支线：佣兵团的模仿者","src_ref":"原刊：上册 第 18 页（《掌机王Plus 异度神剑2 攻略特辑》）","link":"#/mag/vol1-018"},{"src":"assets/mag/vol1-p031.webp","alt":"上册 第 31 页：佣兵团系统说明","caption":"佣兵团系统说明","src_ref":"原刊：上册 第 31 页（《掌机王Plus 异度神剑2 攻略特辑》）","link":"#/mag/vol1-031"}]},{"id":"ch4","num":"第四章","title":"天之圣杯","short":"天之圣杯","badge":"4","color":"cc-bg4","summary":"斯佩比亚篇：光的成长、打捞与倒卖刷发展度、废弃工厂地图，是主角团第一次大幅变强的一章。","place":["斯佩比亚","阿伐利缇亚","古拉","废弃工厂"],"keypoints":[{"text":"本章是「变强」的分水岭：**光的战斗服**免费送、打捞暴富、发展度刷满、[[地标:废弃工厂]]的捷径路线。","kind":"warn","title":"本章优先级"},{"text":"[[地标:废弃工厂]]是主线里最有恶意的关卡之一：多层立体、导航基本失效，按下面的路线走可以直接绕开高级怪。","kind":"tip","title":null}],"steps":[{"title":"完成「[[任务:凡达姆的意志]]」","body":"光离队，焰入队。","notes":[{"text":"系统更新：异刃绑定 MAX 提升至 3，从本章开始能带 3 个异刃战斗。支线解锁：「[[任务:托里格警卫团的委托]]」「[[任务:走在前面的她]]」「[[任务:巨神兽的研究者]]」；异刃任务解锁：「安稳」。","kind":"tip","title":null},{"text":"到这里建议**先推主线把佣兵团系统开了**，再去逛支线。","kind":"tip","title":null}]},{"title":"在[[地标:冯斯麦姆]]港与恰莫莫对话，出发前往阿伐利缇亚","body":"","notes":[]},{"title":"在阿伐利缇亚的[[地标:格尔特蒙特飞行甲板]]搞到去斯佩比亚帝国的票","body":"花 3000G 购买「开往斯佩比亚的船票」。尼娅、白虎、虎、花暂时离队。","notes":[{"text":"支线解锁：「[[任务:扩散传言]]」。","kind":"tip","title":null},{"text":"主线到达斯佩比亚后，回商会打捞甲板找马布马布领取**光的战斗服**——不需要 DLC，只要主线进度到了就送，是光的毕业装备，必拿。","kind":"warn","title":"必拿装备"}]},{"title":"在阿伐利缇亚商会 3 楼的[[地标:莱姆莱伊姆旅店]]与大家会合","body":"","notes":[]},{"title":"从[[地标:格尔特蒙特飞行甲板]]乘上前往斯佩比亚帝国的巨神兽船","body":"尼娅、白虎、虎、花归队。","notes":[]},{"title":"追赶偷走朱雀核心水晶的少年，完成「[[任务:追逐扒手少年]]」","body":"","notes":[]},{"title":"查探古拉・[[地标:乌摩恩造船厂]]的情况，打倒强盗云海鸥 0/4","body":"战斗：Lv22 强盗云海鸥 ×4。","notes":[{"text":"回古拉朱雀觉醒时打强盗的洞穴里可以开宝箱拿到**收纳包扩展工具**，直接传送「[[地标:穿岩之门]]」过去拿，给莱克斯用。","kind":"tip","title":"顺路拿"}]},{"title":"穿过双树之丘的[[地标:穿岩之门]]，前往更深处的强盗老巢","body":"在[[地标:穿岩之门]]剧情强制调谐朱雀，获得朱雀的核心水晶。","notes":[]},{"title":"除去挡在前往强盗老巢道路上的以太瘴气","body":"需要带上朱雀。","notes":[]},{"title":"打倒在强盗老巢的盗贼们 0/3","body":"战斗：Lv24 破坏货车的刚力、Lv25 恐吓的乔、Lv26 策略的尤宾。","notes":[]},{"title":"从[[地标:格尔特蒙特飞行甲板]]乘船前往斯佩比亚","body":"","notes":[{"text":"系统更新：可使用豪迈的核心水晶，现在可以调谐**力男**了。力男战斗力一般，但场景技能非常好，前期很多宝箱和机关都是默认有力男才设计得顺，**强烈建议第一时间开给莱克斯**，没有力男会错过很多内容，之后想换人再用一个超频即可。","kind":"warn","title":"力男必练"},{"text":"花和力男的双地面属性配置最好再搭配一个雷异刃，这样能保证在连锁中破雷球。","kind":"tip","title":null}]},{"title":"为调查前往阿卡狄亚教廷的船，先去一次斯佩比亚的首都","body":"甲板选择搭乘，正式前往斯佩比亚。","notes":[{"text":"系统更新：TIGER! TIGER! 追加新关卡。支线解锁：「[[任务:向帝都进发]]」。","kind":"tip","title":null},{"text":"来到斯佩比亚注意天气：如果是沙尘天气，敌人等级会比平时高。前进右转不远处乘升降梯即到达帝都。","kind":"tip","title":null}]},{"title":"前往[[地标:贾尔卡马洛旅店]]稍事休息","body":"进旅馆花 100G 住宿。","notes":[{"text":"支线解锁：「[[任务:生态调查]]」「[[任务:古代诺彭族的壁画]]」。到了[[地标:帝都阿尔巴马格]]，这里开始有**黄金气瓶**卖，打捞效率提高不少。","kind":"tip","title":null}]},{"title":"赶往[[地标:爱比尔商业区]]的屋顶","body":"系统更新：暂时只能使用光。","notes":[{"text":"光拥有提升全队命中、回避与暴击填充的被动技能，相当强大，可以说接下来焰在战斗中出场机会很少了。","kind":"tip","title":null}]},{"title":"追逐在[[地标:爱比尔商业区]]屋顶逃窜的菊","body":"左侧关闭蒸汽阀门，为右边开路。","notes":[]},{"title":"追逐逃往[[地标:阿达玛仓库区]]屋顶与升降机附近的菊","body":"","notes":[]},{"title":"打倒菊","body":"战斗：Lv29 菊。","notes":[{"text":"Boss 的背面攻击是无视仇恨顺位的，不要在她背面攻击。","kind":"warn","title":null}]},{"title":"打倒梅勒芙等人 0/4","body":"战斗：Lv27 斯佩比亚士兵 ×3、Lv31 梅勒芙。","notes":[]},{"title":"完成「[[任务:菊的去向]]」","body":"","notes":[{"text":"支线解锁：「[[任务:再会]]」。","kind":"tip","title":null}]},{"title":"找守备在斯佩比亚・皇宫哈达夏尔正门的帝国兵对话，向梅勒芙传口信","body":"","notes":[]},{"title":"前往位于斯佩比亚胸部附近的[[地标:废弃工厂]]","body":"","notes":[{"text":"支线解锁：「[[任务:追踪机密文件！]]」。","kind":"tip","title":null},{"text":"前往[[地标:废弃工厂]]的路非常艰险：空间狭小、敌人密集、场景多层立体（一半在上层一半在下层），地图导航基本没用，是主线中非常有恶意的关卡。室内昏暗容易搞不清自己在哪层，**可以根据屏幕右上角的地名来判断位置**。以上层・旧生产区房顶口为 1F 基准：B1＝地热加工室、饱餐食堂、办公室前通道；B2＝热源精炼工作室、德里塞拉医务室；B3＝物资仓库。","kind":"warn","title":"地图要点"},{"text":"有 3 条路通往下层，第 3 种是捷径：①从 B1 饱餐食堂的西侧小洞跳下去，拿到**[[地标:旧街区]]联络门的钥匙**，返回 B1 打开北侧锁住的铁门来到「[[地标:死去劳动者之桥]]」（这里蜥蜴人很多，不必恋战，目标是左下方的梯子，爬梯时会强制脱战）；②进入 B2 后直接往北，用场景技能（火属性之力 Lv3 + 风属性之力 Lv2）破门到达[[地标:死去劳动者之桥]]；③楼梯下到 B2 后往西走，有个隐藏楼梯通往 B3，路上有两只大蜘蛛不用管，直接冲出去，荒原上都是 80 多级敌人也无视，一直往北就到目的地。","kind":"tip","title":"推荐路线"},{"text":"备注给的等价走法：从生产区下第一个楼梯后不要再往下走，右拐前往生产区食堂（入口算 1 楼，食堂算负 1 楼）；食堂地板上 2 个洞，靠近**里面**那个洞跳下去可以拿到联络室钥匙，回到食堂打开联络室的门顺路往下，路上能开的门都开一下（可以开启通往[[地标:旧街区]]的地标「[[地标:死去劳动者之桥]]」），从热源管道第二出口出来后到达荒野，成功避过所有高级怪。","kind":"tip","title":"备注走法"}]},{"title":"打倒齐格 0/1","body":"战斗：Lv32 齐格。","notes":[{"text":"第二次交手多了一招「真霸王雷冥击」，前方 AOE，2 球可以连锁秒杀。","kind":"tip","title":null}]},{"title":"潜入[[地标:废弃工厂]]之中","body":"打开门口红木桶宝箱得到「检查用梯子的钥匙」，去工厂侧面把梯子放下来；破坏换气扇（怪力 Lv2 + 集中力 Lv1），有力男肯定够。","notes":[]},{"title":"探索[[地标:废弃工厂]]内部","body":"左转继续破坏换气扇；打倒火鸡人狱卒 0/4（Lv29 火鸡人狱卒 ×4）。","notes":[]},{"title":"打倒菊 0/1","body":"战斗：Lv31 菊（第二战）。","notes":[]},{"title":"抓住逃往人造异刃调整室的巴恩和木依木依","body":"虎和花暂时离队。从边门出去来到以太管理塔，打倒操作盘前的火鸡人工程师，获得「以太存储罐操作盘的钥匙」，从以太分离罐上方经过到达工厂中心区域。靠近目的地时大门被关，需要去对面制造区监视塔顶层干掉火鸡人警卫来开门；监视塔顶层的门被反锁，要从东侧楼梯绕上去。","notes":[{"text":"与火鸡人警卫战斗前**保存一下**：它有招「绝杀长枪」带倒地特效，如果不幸被倒地，秒你没商量。击败后获得「机库隔离壁的钥匙」，打开大门迎战 Boss。","kind":"warn","title":null}]},{"title":"打倒樱 0/1","body":"战斗：Lv32 樱。打到 80% 发生剧情，虎和花加入队伍。","notes":[{"text":"备注：在[[地标:废弃工厂]]制造区监视塔 4 楼阳台的箱子处（就是打樱之前拿钥匙开大门那栋楼）可以获得**花的第 2 本制作书「人造异刃开发记录」**。","kind":"tip","title":"花的制作书 2"}]},{"title":"追逐并捕捉逃往巴尔吉港的巴恩","body":"","notes":[]},{"title":"打倒弁庆和[[异刃:佐田彦]]，抓住巴恩会长","body":"战斗：Lv33 弁庆、Lv34 [[异刃:佐田彦]]。敌方任意一人 80% 血触发剧情，梅勒芙加入队伍。","notes":[{"text":"[[异刃:佐田彦]]的必杀「星之爆破」会浮空并造成巨大伤害，跑远能躲但很难控制队友，非防御类型挨了必躺，基本是灭团技，而且他还会不停挑衅；相比之下弁庆除了一个地面持续伤害火圈就没什么威胁。**所以战术是快速击倒[[异刃:佐田彦]]**，越快胜算越大。算好血量：当前等级 1 球连锁大概能打[[异刃:佐田彦]]三分之一血，2 球肯定能直接秒杀。","kind":"tip","title":null},{"text":"备注：最终 BOSS 战先打弁庆，再打[[异刃:佐田彦]]；[[异刃:佐田彦]]是 T 有挑衅，挑衅结束后记得切回弁庆，注意不要站在火堆里打弁庆。","kind":"tip","title":null}]},{"title":"斯佩比亚篇的刷钱与打捞路线（第四章重点）","body":"第四章是打捞暴富的最佳窗口，按下面的顺序做效率最高。","notes":[{"text":"① 光彻底解锁后，莱克斯装备光和神八，以及你打算练的一个稀有异刃，然后往收纳包里直接填充 3 次[[物品:迷恋药]]（DLC 限定），再打开他们的牵绊圆环界面解锁。光和神八的信赖度会直接到 A，之前任务获得的[[物品:磁力晶片]]给光用。","kind":"tip","title":"培养顺序"},{"text":"② 菊逃走后，先到**斯佩比亚上层[[地标:采掘长电梯]]前**（重要地标）刷雷光羽蛇：掉落[[物品:牵绊攻击 2]]（尽量多打几个）、[[物品:铁质围额◆◆◆]]；通过战斗把光的技能「光速连击」刷到 5 级、「闪光」4 级。","kind":"tip","title":null},{"text":"③ 用全部身家在斯佩比亚气瓶店买黄金气瓶，莱克斯和尼娅装备之前留下的打捞技术普通异刃，在**斯佩比亚下层港口**打捞。这里不推荐刷太久，刷个 100 多万或 200 万钱就够；打捞的寄居蟹必定掉落核心水晶。打捞时记得积极做佣兵团任务，优先做给商店商品契约书的那些。","kind":"tip","title":"打捞刷钱"},{"text":"④ 在斯佩比亚[[地标:中央交易所]]成套卖掉打捞物品，把斯佩比亚发展度升到 5 星。**卖的时候记得清理增幅器**，不然增幅器满了不给继续卖（增幅器在旁边商店卖掉即可）。","kind":"tip","title":null},{"text":"⑤ 发展度倒卖原理：在高发展度城市低价买气瓶，卖到低发展度城市即可刷对方的发展度。斯佩比亚 5 星后，在打捞店买黄金气瓶 ×99、白银气瓶 ×99，拿去古拉和商会随便找个商店卖掉，就能刷古拉和商会的发展度，重复倒卖可把任何城市刷到 5 星。","kind":"tip","title":"倒卖刷发展度"},{"text":"⑥ 返回斯佩比亚旅店温泉处获取**第 3 个超频**。","kind":"tip","title":"必拿道具"},{"text":"⑦ 在斯佩比亚下层主线前往首都的路上，刷大陆狼兽和亡者巨蜂可以爆 3 星[[物品:经典奖章◆◆◆]]（暴击回血 12%），给莱克斯装备上。","kind":"tip","title":null},{"text":"⑧ 邪道技巧（买了 DLC 才有）：在设定里开「定制模式」，把敌人血量设到最低、自己有利的设定全开最强，刷完再改回来。这会严重破坏游戏体验，主要照顾没时间的玩家。","kind":"tip","title":"速通向"}]},{"title":"第四章装备与异刃配置建议","body":"备注给出的成型配置，可直接照抄。","notes":[{"text":"**莱克斯**：异刃＝光、斧系武器异刃、神八；饰品＝[[物品:经典奖章◆◆◆]]（暴击回血 12%）、[[物品:铁质围额◆◆◆]]（爆伤 30%）；光的辅助核心＝[[物品:牵绊攻击 2]] + 光的战斗服；神八的辅助核心＝[[物品:牵绊攻击 2]]、[[物品:会心提升 2]]、以及[[物品:高 HP 攻击]]/[[物品:室外攻击]]/[[物品:室内攻击]]/[[物品:牵绊回避]]（选一，有啥用啥）；斧系异刃＝[[物品:切换缩短 2]] + 同类选项。","kind":"tip","title":"配置模板"},{"text":"**尼娅**：异刃＝白虎、火花、拳套类/以太炮系；饰品＝[[物品:丰饶项饰]]、[[物品:佣兵背心]]；白虎辅助核心＝[[物品:牵绊攻击 2]] + [[物品:高 HP 攻击]]/[[物品:室外攻击]]/[[物品:室内攻击]]/干扰（选一）；火花辅助核心＝[[物品:牵绊攻击 2]]、[[物品:融合连击 2]]、以及同类选项，火花记得把会破防的武技换上。","kind":"tip","title":null},{"text":"**虎**：异刃＝花 JS；饰品＝诺彭面具、[[物品:深渊背心]]；花的配置——战斗类别：防御定制；属性核心：地属性核心；武技卡：AC 弱化重置、AC 获取仇恨值；技能 RAM：[[物品:武技仇恨值上升]]；必杀技强化 RAM：SP 正面特效；扩张技能：[[物品:牵绊壁障]]、仇恨值上升。","kind":"tip","title":null},{"text":"没买 DLC 的替代方案：莱克斯的神八换成朱雀；尼娅用白虎、拳套武器、以太炮武器/弹击球。","kind":"tip","title":null}]},{"title":"斯佩比亚下层与秘境（可顺路拿）","body":"","notes":[{"text":"① 顺着垃圾输送带走到尽头的垃圾堆，那里有个像下水管一样的管子，从管子滑下去在尽头跳下，顺着铁丝网往上爬，通过一个场景技能点可到达秘境**空中回廊**。","kind":"tip","title":"秘境"},{"text":"② 通过「[[地标:死去劳动者之桥]]」到达[[地标:旧街区]]后，顺着路一路向上走（需通过一个场景技能点）可达秘境**诺彭开拓者的秘密温泉**。","kind":"tip","title":null},{"text":"③ 备注给的刷晶片位置：从热源管道第二出口出来到达荒野，可以看见蜥蜴人突击兵（骑着游牧莱诺兽），或通过[[地标:死去劳动者之桥]]到达[[地标:旧街区]]看到蜥蜴人队长，这两种怪物会爆[[物品:绿草晶片]]（暴击率最高的紫色晶片），记得先刷 2 个给光和神八。光（闪光 5 级 + 光的战斗服）暴击率最高可达 47%，神八（[[物品:会心提升 2]]）直接 50%。","kind":"tip","title":"刷晶片"}]}],"diffs":[{"src":"《每章更多备注》","text":"备注对本章的评价是「本攻略最激进的部分」：如果完全照做，主角团会迎来第一次飞跃式成长——莱克斯与尼娅点亮「武技取消武技」，在 DLC [[物品:迷恋药]]加成下光的成长速度惊人，同级别精英 BOSS 基本不成问题。斯佩比亚还有一部分内容因为关键人物未入队做不了，放到第 5 章开篇介绍。"},{"src":"《攻略特辑》（掌机王Plus）","text":"《攻略特辑》在连锁攻击的总结里提醒：连锁攻击最好在全队血量 70% 以上时发动，因为它会清空小队槽，如果没能借此消灭敌人，接下来可能面临减员又无法复活的局面；小队槽战斗后不会被清空，可以提前攒好再挑战 BOSS 或稀有怪。"}],"quests":["凡达姆的意志","托里格警卫团的委托","走在前面的她","巨神兽的研究者","安稳","扩散传言","追逐扒手少年","向帝都进发","生态调查","古代诺彭族的壁画","菊的去向","再会","追踪机密文件！"],"images":[{"src":"assets/mag/vol1-p016.webp","alt":"上册 第 16 页：第 4 章：凡达姆的意志 / 佣兵团","caption":"第 4 章：凡达姆的意志 / 佣兵团","src_ref":"原刊：上册 第 16 页（《掌机王Plus 异度神剑2 攻略特辑》）","link":"#/mag/vol1-016"},{"src":"assets/mag/vol1-p017.webp","alt":"上册 第 17 页：神秘零件与阿伐利缇亚的真相","caption":"神秘零件与阿伐利缇亚的真相","src_ref":"原刊：上册 第 17 页（《掌机王Plus 异度神剑2 攻略特辑》）","link":"#/mag/vol1-017"},{"src":"assets/mag/vol2-p020.webp","alt":"下册 第 20 页：第 4 章流程：菊的去向 / 废弃工厂","caption":"第 4 章流程：菊的去向 / 废弃工厂","src_ref":"原刊：下册 第 20 页（《掌机王Plus 异度神剑2 攻略特辑》）","link":"#/mag/vol2-020"}]},{"id":"ch5","num":"第五章","title":"枷锁","short":"枷锁","badge":"5","color":"cc-bg5","summary":"利贝拉里塔斯群岛 + 檀佩兰提亚：大型刷装备与刷级窗口，稀有异刃入队任务集中，七冰是本章的关键异刃。","place":["利贝拉里塔斯群岛","弥先村","阿卡狄亚","檀佩兰提亚"],"keypoints":[{"text":"本章是**中期最长的自由活动窗口**：群岛左右两条路线、檀佩兰提亚刷级刷金片，都可以在这里做满。","kind":"warn","title":"本章节奏"},{"text":"必做支线：斯佩比亚首都商业区找八千矛领的**「[[任务:再会]]」**——它是「斯佩比亚帝国反叛组织」大型系列支线的第一环，拿到[[地标:贝菲拉工业区]]厂区钥匙，而且是最终章刷[[物品:牵绊攻击 5]] 的前置（主体游戏里最多只爆到[[物品:牵绊攻击 5]]，[[物品:牵绊攻击 6]] 只能在 DLC 挑战模式低概率出）。","kind":"warn","title":"必做支线"},{"text":"群岛右边路线的怪比左边高 5~10 级，建议第一次走左边，全员归队后再从起点重走一次右边。","kind":"tip","title":null}],"steps":[{"title":"在阿卡狄亚巨神兽船的露台上随便逛逛","body":"与芳对话选择「休息」。尼娅、虎、梅勒芙暂时离队。","notes":[{"text":"系统更新：光和焰之间能自由转换。","kind":"tip","title":null}]},{"title":"前往莱克斯的故乡[[地标:弥先村]]","body":"尼娅、虎、梅勒芙入队。","notes":[{"text":"支线解锁：「[[任务:阿伐利缇亚的真相]]」「[[任务:音讯不明]]」「[[任务:搜寻密探]]」「[[任务:第一次旅行]]」「[[任务:抱头烦恼的商人]]」。","kind":"tip","title":null},{"text":"梅勒芙之后还有几次要暂时离队，**先不急着培养**。往北有两条路，右边路上都是 40 多级敌人，走左边的路。","kind":"tip","title":null}]},{"title":"探索[[地标:弥先村]]","body":"云海道中间没路了，去旁边摸一下反射中枢；前往村子北面的奥拉希昂丘墓。尼娅、虎、梅勒芙暂时离队。","notes":[]},{"title":"去找在[[地标:弥先村]]自宅等待的柯蕾尔阿姨对话","body":"","notes":[]},{"title":"前往[[地标:弥先村]]相邻岛屿的[[地标:伊谢巴港]]","body":"尼娅、虎、梅勒芙归队。","notes":[{"text":"支线解锁：「[[任务:被偷走的回忆]]」。","kind":"tip","title":null}]},{"title":"打倒齐格 0/1","body":"战斗：Lv35 齐格。梅勒芙离队。","notes":[{"text":"如果之前用的是梅勒芙当坦克，这里要把虎换上来（可以选三个人：别进战斗，按 + 点角色，然后按 X 进队伍分配，方向键拉到最右边，按 X 把没进队伍的加入队伍）。","kind":"tip","title":"换人方法"},{"text":"新技能「超音速雷神皇帝剑」伤害巨大，能直接秒虎，建议利用连锁攻击的无敌时间来对付。","kind":"warn","title":null}]},{"title":"在阿卡狄亚的城镇[[地标:哥特伊斯沃特]]随便逛逛","body":"梅勒芙入队；进入[[地标:阿卡狄亚大圣堂]]在住宿处休息（选择「是」）。","notes":[]},{"title":"为觐见麦佩尼，前往[[地标:阿卡狄亚大圣堂]]觐见室","body":"","notes":[{"text":"支线解锁：「[[任务:圣歌队的梅丽卡]]」。","kind":"tip","title":null}]},{"title":"和[[地标:阿卡狄亚大圣堂]]的阿玛利亚对话并稍事休息，随后赶往觐见室","body":"","notes":[]},{"title":"追逐梅勒芙，前往罗德里希所在的来宾室","body":"梅勒芙离队。随后为前往檀佩兰提亚赶去[[地标:哥特伊斯沃特]]港，梅勒芙入队。","notes":[{"text":"支线解锁：「[[任务:阿卡狄亚的教义]]」。","kind":"tip","title":null}]},{"title":"和停泊在[[地标:哥特伊斯沃特]]港的提穆尔对话，出发前往檀佩兰提亚","body":"齐格入队。","notes":[]},{"title":"破坏电力线，停止阿耶修玛・核心的活动 0/1","body":"战斗：Lv36 电力线、Lv38 阿耶修玛・核心。","notes":[{"text":"阿耶修玛・核心每 2 秒回复四分之一血，所以真正的目标是后面的**电力线**。电线半血后有极高的反弹伤害，但总血量很少，半血后 1 球连锁就足够击杀；如果队伍槽没满，让队友集火旁边那个大家伙攒槽。","kind":"tip","title":"打法要点"},{"text":"备注补充：BOSS 战时的机器在切断电缆线之前基本无敌，所以必须先打电缆线（**电缆线也是有血量的**）；电缆线血量降到半血左右会有反伤，如果提前给光、神八等主力输出异刃装备「[[物品:反噬防御]]」（在英维迪亚烈王国腹部・[[地标:圣域的王冠]]打光彩巨蜂概率掉落），会轻松一些，否则请在电缆线半血前速上 3 球，半血进连锁秒掉。","kind":"tip","title":null},{"text":"收纳道具建议：第一个收纳包填「[[物品:热红宝石蒸汽面包]]」（斯佩比亚甜品店购买，需要做佣兵任务拿到契约书）或[[物品:纳西梨果冻]]，最后一个包填当前能买到的最高级[[物品:耽美绅士之书]]。打真时只需要注意他的 4 连，别让他秒掉莱克斯，仇恨尽量让 T 拉住。","kind":"tip","title":null}]},{"title":"打倒真 0/1","body":"战斗：Lv40 真。真使用「胧燕」时攻击他会被浮空，玩家控制的角色要及时停手。","notes":[]},{"title":"打倒阿耶修玛・核心 0/1","body":"战斗：Lv38 阿耶修玛・核心。木桩 Boss，只能打出破防和倒地，打不出浮空。","notes":[]},{"title":"稀有异刃入队任务（本章集中开启）","body":"主线到达里贝拉利塔斯群岛、梅勒芙正式入队后，下列异刃入队任务都可以做了。","notes":[{"text":"**结**：白天在古拉托德里格镇市场找结领取任务；「[[物品:苦味巧克力]]」在英维迪亚烈剧场门口的小摊贩处购买；任务最后要去斯佩比亚的**[[地标:遗忘封地]]**（秘境），找不到可以查视频或图文。在[[地标:遗忘封地]]拿到结的任务道具后别急着走，**斯佩比亚下层南阿姆大门的钥匙也在这里**，记得拿。归属建议：结给尼娅。","kind":"tip","title":"结"},{"text":"**水分**：在斯佩比亚情报商人处购买「[[任务:核心水晶猎手]]」的情报，获取入队任务；身上带 10 个以上核心水晶，前往古拉第一次遇见[[异刃:迦具土]]的地方触发任务；任务最终要你去的地方是从斯佩比亚上层采掘场电梯前坐电梯下去，左边管道走到头。归属建议：留着不开。","kind":"tip","title":"水分"},{"text":"**重音**：在斯佩比亚情报商人处购买「大胃王尖角龙鱼」的情报后，去斯佩比亚下层南阿姆大门打捞点打捞（需要先去[[地标:遗忘封地]]拿阿姆大门的钥匙开门）。这个打捞点有概率捞出 40 多级的怪物尖角龙鱼，杀死后获得重音的核心水晶。技巧：想更容易捞出怪物，用**普通气瓶、按键挑战全部故意失败、不要装备打捞技术的普通异刃**。归属建议：重音给梅勒芙。","kind":"tip","title":"重音"},{"text":"**凛音**：在[[地标:托里格镇]]杂货店花 50 万直接购买核心水晶（就是第二章主线买花的零件时看到的那个）。归属建议：不开，或者给莱克斯。","kind":"tip","title":"凛音"},{"text":"**[[异刃:花巴斯塔]]**：DLC 限定稀有异刃。第 4 章结束后返回虎的家里触发任务，任务简单但繁琐，就是让你用各种普通异刃按要求释放必杀技，按要求做即可。[[异刃:花巴斯塔]]是共有异刃，不存在归属问题。","kind":"tip","title":"花巴斯塔"}]},{"title":"利贝拉里塔斯群岛：左路线要点","body":"第一次来建议走左边（怪 45~50 级），路上内容以牵绊对话与开环怪为主。","notes":[{"text":"① 左边路线的尖啄鹰繁殖基地可以观看牵绊对话「花的形态」。","kind":"tip","title":"左路线"},{"text":"② [[地标:弥先村]]莱克斯的秘密基地可以观看牵绊对话「柯蕾尔阿姨家」，在房子后面云海边上这块区域找，需要场景技能。","kind":"tip","title":null},{"text":"③ 群岛上有很多可以激活异刃牵绊圆环技能的怪物，涉及光、焰、白虎、神八、[[异刃:迦具土]]等一批**没法通过佣兵任务激活技能**的异刃，建议对着要求逐个激活。","kind":"tip","title":null},{"text":"④ 到了 REX 村子过夜、全员归队后不要直接出发坐船（其实坐船后也能传送回来），从起点重走一次右边路线。","kind":"tip","title":null}]},{"title":"利贝拉里塔斯群岛：右路线要点","body":"右路线怪 50~60 级且有多只冠名怪，但资源价值很高。","notes":[{"text":"① **[[地标:遗迹沉睡之岛]]**（重要地标）：涉及非常多的支线任务与异刃技能激活需要打的怪物。这里说三个怪——疾速羽毛龙、疾飞翻天鳐、精英 BOSS [[敌人:疾风的王冠虾]]；其中疾飞翻天鳐掉落 [[物品:黄金诺彭面具◆◆◆]]（[[物品:嘲讽面具◆◆◆]]），疾速羽毛龙是烟解锁技能需要打的怪，精英 BOSS [[敌人:疾风的王冠虾]]涉及好几个稀有异刃技能的激活（现在不用打，记住它就好）。","kind":"tip","title":"右路线"},{"text":"② **[[地标:传承之盆景]]**（这个岛没有地标）：从[[地标:遗迹沉睡之岛]]跳云海里有过去的一座小岛，岛上精英 BOSS「[[敌人:迷宫的修特罗姆]]」（龙鱼）同样是烟、[[异刃:八重切]]等好几个稀有异刃解锁技能需要打的精英怪，也是凛音异刃支线要去的地方；凛音支线结束后那 100 万贝里可以在这个岛上挖掘拿回来（需要超高级场景技能，不是后期基本没希望）。","kind":"tip","title":null},{"text":"③ **[[地标:路德云海隧道]]**：里面的福波利海豚蜥是白虎激活技能需要打的怪；精英 BOSS「[[敌人:美食的洛奇]]」是[[异刃:迦具土]]等几个稀有异刃将来激活技能需要打的 BOSS；隧道出口是[[异刃:宫比罗]]牵绊对话的地点（需要配置[[异刃:宫比罗]]在诺彭商会旅馆睡觉后激活）；火花支线剧情任务的最终 BOSS 点也在这里。","kind":"tip","title":null},{"text":"④ **[[地标:神渡之岛]]**（重要地标）：也涉及大量支线与异刃技能激活怪。**第 4 个收纳包扩展工具**拿法：传送[[地标:神渡之岛]]后立刻往身后跑，在尽头跳到那个会移动的空中小岛上，在移动小岛经过的某个空中小岛上有箱子，开启后获得。","kind":"tip","title":"收纳包 4"},{"text":"⑤ **[[地标:伊谢巴港]]**：主线前往教廷的最终地点，大名鼎鼎的[[物品:加速护腕◆◆◆]]就在这里刷——岛上 39 级人型精英 BOSS「[[敌人:天伦拳的里奇]]」概率爆 [[物品:加速护腕◆◆◆]]，这是素质四连的基础饰品之一，必定要刷。","kind":"tip","title":"必刷饰品"}]},{"title":"檀佩兰提亚与刷级刷装备路线（本章重点）","body":"刷到 65 级、拿[[物品:黄金晶片]]与增刊号，是中期最有效的变强手段。","notes":[{"text":"① 在诺彭商会莫奇莫奇（商会 3 楼跳过去）处可以评定你的打捞等级。","kind":"tip","title":"檀佩兰提亚"},{"text":"② 第五章与伊拉一伙 BOSS 战结束后，在教会找诺彭旅行商人库库恩领取支线**「[[任务:追求新天地]]」**（顺路接一下，也给路痴大致方向）。做到「在檀佩兰提亚收集各种道具交给库库恩 0/100」时可能卡住：采集很多却还是 0/100，**因为需要返回营地找库库恩上交材料才会增加进度**。","kind":"tip","title":null},{"text":"③ 回到檀佩兰提亚与伊拉一伙 BOSS 战的地方，从巨神兽身上一步步跳下去可到达檀佩兰提亚的中央平原。中央平原上许多怪物是异刃技能解锁需要打的（光、焰、白虎、[[异刃:迦具土]]这些一周目卸不下来做佣兵任务的），请自行查看要求。","kind":"tip","title":null},{"text":"④ 檀佩兰提亚中央・袭击飞天鳐可以掉落 3 星[[物品:钛制背心◆◆◆]]（貌似最牛的加血百分比背心），可以考虑刷 2 个过渡。","kind":"tip","title":null},{"text":"⑤ 从巨神兽身上跳下去的地方往左一直走，通过中央平原可以看到斯佩比亚军驻地，驻地左前方可前往[[地标:古代都市尤迪肯姆]]。","kind":"tip","title":null},{"text":"⑥ 斯佩比亚军驻地前往的海边可以遇到 60 级**[[敌人:泽奥斯斑点龙鱼]]**，掉落[[物品:黄金晶片]]、「[[物品:从零开始的战斗讲座·增刊号◆]]」、[[物品:英雄护腕]]。主要刷[[物品:黄金晶片]]和增刊号：[[物品:黄金晶片]]让掉宝率增加 50%，增刊号是唯一增加战斗经验的饰品。莱克斯 50 多级带上暴击回血和[[物品:钛制背心◆◆◆]]不会被秒杀，然后速度上球进连锁秒掉。建议在这里直接刷到 65 级（刷级记得带增刊号）；[[物品:黄金晶片]]可以给进行猛击的异刃带，嫌麻烦就全员黄金也行。**增刊号只需要 2~3 个**即可，因为此地形太不适合刷怪；要专门刷[[物品:黄金晶片]]请看下一条刷[[敌人:吸血贵妇人玛蒙]]的部分。","kind":"tip","title":"刷级点"},{"text":"⑦ 刷到 65 级后（本作等级压制很明显），回到古拉[[地标:朽木之岛]]高级怪聚集点（[[地标:朽木之岛]]到瓦斯克纳大瀑布的通道）刷 72 级蝙蝠群 / [[敌人:食蛙的史尼克]]（75 级精英 BOSS），掉落 [[物品:贝塔瞄准镜◆◆]]（只有二星款），装备给尼娅。","kind":"tip","title":null}]},{"title":"史诗核心水晶获取：刷[[敌人:吸血贵妇人玛蒙]]","body":"在英维迪亚烈腹部・[[地标:龙之胃]]，用素质四连刷 65 级精英 BOSS「[[敌人:吸血贵妇人玛蒙]]」，可概率掉落史诗核心水晶。刷之前先清掉周围小怪。","notes":[{"text":"队伍配置（备注给出版本）——**莱克斯**饰品：[[物品:加速护腕◆◆◆]]、[[物品:经典奖章◆◆◆]]；异刃：光（[[物品:绿草晶片]]、切换缩短、光的战斗服，负责倒地）、斧系异刃（[[物品:黄金晶片]]、切换缩短、[[物品:室内攻击]]，负责浮空）、神八/朱雀（[[物品:黄金晶片]]、切换缩短、[[物品:牵绊回避]]/牵绊攻击/[[物品:室内攻击]]，负责猛击）。**尼娅**饰品：[[物品:贝塔瞄准镜◆◆]]、[[物品:加速护腕◆◆◆]]；异刃：白虎（[[物品:黄金晶片]]、干扰、[[物品:牵绊壁障]]）、弹击球系（火花：[[物品:黄金晶片]]、牵绊攻击、必杀技强化 2/[[物品:室内攻击]]、切换缩短/融合连击）、以太炮系（[[物品:黄金晶片]]、切换缩短、[[物品:室内攻击]]）。**虎**：[[物品:黄金诺彭面具◆◆◆]]、[[物品:钛制背心◆◆◆]]；花：[[物品:黄金晶片]]，其它参考前面。","kind":"tip","title":"配置模板"},{"text":"缺少饰品、辅助核心或材料时，可到乐园数据管理室 wiki 自行查询。玛蒙算是史诗核心水晶掉率与击杀难度相对平衡的精英 BOSS，中期基本就刷它；刷多久看需求，**保底至少把七冰抽出来**，其它比较理想的异刃有[[异刃:八重切]]、宇迦、KOS-MOS Re、[[异刃:宫比罗]]、蓟、[[异刃:韦驮天]]。","kind":"tip","title":null}]},{"title":"七冰：中后期最重要的「幼儿园老师」异刃","body":"如果第 4 章或第 5 章能开到七冰，强烈建议立刻投入使用。","notes":[{"text":"七冰战斗不算强，但她的支线任务与开环需要做巨量佣兵任务，而且七冰的佣兵任务单次时间不长，**非常适合用来给其它稀有异刃批量激活技能**（自己一个个手刷会刷死），顺便还能刷佣兵团等级。","kind":"tip","title":"七冰用法"},{"text":"补充说明（备注版）：想要 5000 粉丝，除了刷徽章的任务外，只要三个课程都升到 LV5 并完成，留意每个地区都会出现红色的**七冰专属演唱会佣兵任务**——把这些专属任务做了，比闷头只刷徽章粉丝涨得快得多，不需要三个徽章都 99，多做演唱会任务即可。","kind":"tip","title":null}]}],"diffs":[{"src":"《攻略特辑》（掌机王Plus）","text":"《攻略特辑》对本章的连锁与融合连击补充较多：融合连击＝御刃者连击与异刃连击重合发动，此时画面会短暂停顿并出现文字提示（例如倒地、浮空）。除伤害提升外，两种连击的持续时间也会延长，同时发动连锁攻击所需的能量槽也会增加。判定成功看画面会同时出现武技反应动作的名字与必杀技连击的名字。"},{"src":"《每章更多备注》","text":"备注版对融合连击的实战评价更直接：原理简单但需要理解战斗体系——队伍搭配、异刃选择、饰品与辅助核心、收纳道具、时机把握都很重要。常用的是火花与宇迦（被动都有融合连击增伤，土+火是完美配置）。但普通难度下新人不必把它当主要输出手段，真想玩好融合连击基本要二周目起步。备注还提示本章剧情会给力男异刃，务必第一时间开给莱克斯：力男战力一般但场景能力极好，前期很多宝箱和机关默认按有力男设计，缺了会错过很多，后期想换人一个超频就够了，很划算。"}],"quests":["阿伐利缇亚的真相","音讯不明","搜寻密探","第一次旅行","抱头烦恼的商人","被偷走的回忆","圣歌队的梅丽卡","阿卡狄亚的教义","追求新天地","乌摩恩重振旗鼓","反帝国组织的调查","尤迪肯姆的遗产"],"images":[{"src":"assets/mag/vol2-p021.webp","alt":"下册 第 21 页：第 5 章：焰光自由切换 / 云海道","caption":"第 5 章：焰光自由切换 / 云海道","src_ref":"原刊：下册 第 21 页（《掌机王Plus 异度神剑2 攻略特辑》）","link":"#/mag/vol2-021"},{"src":"assets/mag/vol2-p022.webp","alt":"下册 第 22 页：第 5 章 BOSS：阿耶修玛·核心与电力线","caption":"第 5 章 BOSS：阿耶修玛·核心与电力线","src_ref":"原刊：下册 第 22 页（《掌机王Plus 异度神剑2 攻略特辑》）","link":"#/mag/vol2-022"},{"src":"assets/mag/vol1-p009.webp","alt":"上册 第 9 页：异刃任务：水分（核心水晶猎手）","caption":"异刃任务：水分（核心水晶猎手）","src_ref":"原刊：上册 第 9 页（《掌机王Plus 异度神剑2 攻略特辑》）","link":"#/mag/vol1-009"},{"src":"assets/mag/vol2-p032.webp","alt":"下册 第 32 页：全异刃收集 / 卢加大瀑布","caption":"全异刃收集 / 卢加大瀑布","src_ref":"原刊：下册 第 32 页（《掌机王Plus 异度神剑2 攻略特辑》）","link":"#/mag/vol2-032"}]},{"id":"ch6","num":"第六章","title":"伤痕","short":"伤痕","badge":"6","color":"cc-bg6","summary":"从阿卡狄亚经洛修利亚进发：本章中后段开始队员长期缺员，是「想跑支线就到此为止」的分界线。","place":["阿卡狄亚","哥特伊斯沃特港","洛修利亚"],"keypoints":[{"text":"重要提醒：主线推进到洛修利亚的**[[地标:圣战遗址]]**就要止步——之后直到第八章全员集合（跨第六章结尾 BOSS 战、整个第七章、第八章前半），大部分支线、地图探索与异刃羁绊开环任务都无法进行（佣兵团任务不受影响）。","kind":"warn","title":"止步点"}],"steps":[{"title":"前往[[地标:阿卡狄亚大圣堂]]的教皇办公室","body":"","notes":[{"text":"支线解锁：「[[任务:乌摩恩重振旗鼓]]」「[[任务:反帝国组织的调查]]」「[[任务:追求新天地]]」「[[任务:尤迪肯姆的遗产]]」。","kind":"tip","title":null}]},{"title":"出席在[[地标:塞利利欧斯广场]]举办的芳・勒・诺伦的国葬","body":"梅勒芙离队。随后响应麦佩尼的号召前往教皇办公室，为商讨今后去路回到客房留宿（选择「是」休息）。","notes":[]},{"title":"为了去洛修利亚，穿过珀尔迪斯圆形广场前往[[地标:哥特伊斯沃特]]港","body":"","notes":[]},{"title":"完成「[[任务:巴恩的阴谋]]」","body":"","notes":[]},{"title":"赶往停泊在[[地标:哥特伊斯沃特]]港的斯佩比亚巨神兽战舰内的厨房，打倒火鸡人 0/4","body":"战斗：Lv39 火鸡人 ×4。","notes":[]},{"title":"赶往战舰内的机库，打倒Ｇ樱 0/1","body":"战斗：Lv42 Ｇ樱。胜利后获得**收纳包扩张工具**。","notes":[{"text":"G 樱比原版樱强了许多：火箭砰砰（范围倒地，紧接踩地浮空）、导弹钻钻（全体伤害）、光束滚滚（范围吹飞）、超能爆爆（设置一个 15 秒后爆炸的定时导弹）、超能电电（范围吹飞）。最有威胁的是超能爆爆召唤的定时导弹，没 4000 HP 挨一下非死即残。","kind":"warn","title":"G 樱技能"},{"text":"合理战术：利用火属性异刃连击终结的**封印自爆**效果，无视导弹自爆。Boss 大概 60% 血开始使用超能爆爆，安排第 2 轮异刃连击封印自爆基本正好覆盖，等第 3 轮异刃连击后直接进连锁，3 球足够打掉一半血。","kind":"tip","title":null}]},{"title":"找巨神兽船船长欧拉拉对话，出航前往洛修利亚","body":"梅勒芙入队。","notes":[]},{"title":"向洛修利亚的王都进发","body":"系统更新：TIGER! TIGER! 追加新关卡。穿过特奥斯奥莱正门前往王宫[[地标:特奥斯卡尔迪亚]]。","notes":[{"text":"支线解锁：「[[任务:凯尼蒂亚的烦恼]]」。","kind":"tip","title":null}]},{"title":"前往[[地标:特奥斯卡尔迪亚]]觐见大厅，救出被移送到王宫地下的焰","body":"焰、齐格离队；没走几步齐格回队。焰不在，尽量避免战斗，直冲最深处；随后打倒洛修利亚骑士 0/6（Lv42 洛修利亚骑士 ×6）。","notes":[]},{"title":"向特奥斯皮斯缇神殿遗迹深处前进，赶往三圣颂锁链所在的地方","body":"从王都南面出来，目标是[[地标:卢米娜利亚支柱]]；[[地标:双子支柱]]处断桥，破坏冰层后推倒冰柱；到达[[地标:卢米娜利亚支柱]]后沿路一直往下走，到了下层[[地标:玄武大雪原]]一直往西。","notes":[{"text":"支线解锁：「[[任务:丢失的宝物]]」「[[任务:协助执笔]]」。","kind":"tip","title":null},{"text":"备注补充：前往洛修利亚头部的路是从王都后门出去直走，到达阿姆雷特支柱后往下走，**[[地标:双子支柱]]处需要推倒冰柱搭桥**；[[地标:双子支柱]]那里有个从尸体上捡到字条的支线任务，简直是白送的，可以顺道接。","kind":"tip","title":null},{"text":"备注补充：通过[[地标:双子支柱]]后顺路可以到达**[[地标:渴望眼界]]**。注意墙壁上吸附着的 42 级「[[敌人:托托里奥翻天鳐]]」（老板鱼），掉落 [[物品:爆裂标志◆◆◆]]——这是连锁攻击打法最核心的毕业饰品，人手固定一个饰品槽位；如果打不到，记得换以太炮异刃来引怪。如果是雾天来[[地标:渴望眼界]]，墙上的老板鱼会变成 80 多级，击杀会掉落辅助核心「[[物品:切换缩短 5]]」。","kind":"warn","title":"必刷：[[物品:爆裂标志◆◆◆]]"},{"text":"备注补充：从[[地标:渴望眼界]]继续顺路走会到达[[地标:卢米娜利亚支柱]]。支柱右边的路是前往洛修利亚下层大雪原的路（主线），左边跳下去是前往秘境**空中宝座**的路。空中宝座是全游戏最重要的秘境之一：有几个稀有异刃技能激活需要到这里，而且它是前往[[地标:封闭矿石厂]]最近的地标，[[地标:封闭矿石厂]]是[[物品:迷恋药]]主材料「心跳蓟」的采集点。路线需要场景技能【冰属性之力 LV6、集中力 LV5】一路开冰桥过去，再需要【风属性之力 LV7、跳跃 LV5】才能抵达。","kind":"tip","title":"秘境：空中宝座"},{"text":"备注补充：顺着[[地标:卢米娜利亚支柱]]右边的路一路向下可到达[[地标:卢米娜利亚台座]]，台座前方就是大雪原，雪原中心部位是重要地标**[[地标:中央以太岩石]]**。台座后方可以接一个比较重要的支线（写书的妹子），完成后可以在洛修利亚书店买到一本 [[物品:耽美绅士之书]]。洛修利亚书店有两本重要的收纳道具：做佣兵任务后解锁购买的「[[物品:天文占卜大词典]]」，以及这个妹子写的书。另外[[异刃:宫比罗]]的支线需要集齐商会、英维迪亚烈、洛修利亚三个书店的店契。","kind":"tip","title":null}]},{"title":"穿过圣大列柱廊与[[地标:圣战遗址]]，赶往三圣颂锁链","body":"","notes":[{"text":"到这里就是本轮自由活动的止步点——继续推进主线后（直到第八章全员集合）大部分支线与羁绊任务无法进行。","kind":"warn","title":"止步点提醒"}]},{"title":"打倒伊拉的三人 0/3","body":"战斗：Lv42 弁庆、Lv43 义经、Lv44 [[异刃:佐田彦]]。","notes":[{"text":"群战三人组，难度意外地不高。弁庆不一会儿会召唤一个天气变化装置，会不停释放「异刃连击缩短」的效果，这要求我方 3 人连续使用必杀才能达成异刃连击；好在并没有其他强力招数，慢慢磨血都能赢。","kind":"tip","title":null}]},{"title":"打倒真 0/1","body":"战斗：Lv46 真。80% 触发剧情，之前一战留有队伍槽的话可以直接发动连锁。战后焰离队。","notes":[]}],"diffs":[{"src":"《每章更多备注》","text":"备注把这一段的时间账算得很清楚：从第六章主线推进到「到洛修利亚头部获得三圣颂锁链」起，到第八章全员集合为止，足足一个半章节的时间段里，大部分支线、地图探索、异刃羁绊开环任务都无法进行（佣兵团任务不影响），因为主角队缺人。所以如果还想跑支线、跑地图到处逛，地图推到洛修利亚的[[地标:圣战遗址]]就要止步。"}],"quests":["乌摩恩重振旗鼓","反帝国组织的调查","追求新天地","尤迪肯姆的遗产","巴恩的阴谋","凯尼蒂亚的烦恼","丢失的宝物","协助执笔"],"images":[{"src":"assets/mag/vol2-p023.webp","alt":"下册 第 23 页：第 6 章：王都特奥斯奥莱地图与王宫","caption":"第 6 章：王都特奥斯奥莱地图与王宫","src_ref":"原刊：下册 第 23 页（《掌机王Plus 异度神剑2 攻略特辑》）","link":"#/mag/vol2-023"},{"src":"assets/mag/vol1-p021.webp","alt":"上册 第 21 页：阿卡狄亚教廷支线（时限警告）","caption":"阿卡狄亚教廷支线（时限警告）","src_ref":"原刊：上册 第 21 页（《掌机王Plus 异度神剑2 攻略特辑》）","link":"#/mag/vol1-021"}]},{"id":"ch7","num":"第七章","title":"崭新的利剑","short":"崭新的利剑","badge":"7","color":"cc-bg7","summary":"艾尔皮斯灵洞 + 莫尔斯断崖：全游戏最复杂的迷宫与的高难度 BOSS 战，同时也是中后期刷毕业装备的关键窗口。","place":["洛修利亚","艾尔皮斯灵洞","莫尔斯断崖"],"keypoints":[{"text":"第六章到第八章之间是「主角队缺人」的空窗期，但第七章开头的[[地标:洛修利亚王都]]仍有一批可做的事：花的第 3 本制作书、天威的供奉祭坛、[[物品:爆裂标志◆◆◆]]与[[地标:渴望眼界]]。","kind":"tip","title":"本章节奏"},{"text":"[[地标:艾尔皮斯灵洞]]会限制以太流：深处回血量降低，而且只能用第一段必杀技，同等级下难度明显更高，建议多利用素质四连。","kind":"warn","title":null}],"steps":[{"title":"响应洛修利亚王的号召，前往[[地标:特奥斯卡尔迪亚]]觐见大厅","body":"","notes":[{"text":"支线解锁：「[[任务:巴恩的秘密财产！？]]」「壁画之谜」「[[任务:汇款流程]]」「[[任务:过去的光辉]]」「好搭档」。","kind":"tip","title":null}]},{"title":"[[地标:洛修利亚王都]]可做的事（第七章上）","body":"主线开启[[地标:洛修利亚王都]]剧情后，先别急着往下推，王都里有一批高价值内容。","notes":[{"text":"① 在**奉迎大厅牢房**出来后，出门直接左拐，通过一段向下的楼梯后开门进入**[[地标:物质保管库]]**，开宝箱获得**花的第三本零件制作书**。虽然拿到制作书，但花的成型还是慢，现阶段仍只能老实当 T；不想肝小游戏可以二周目用大量经验换零件和以太结晶，但一周目不追求全零件毕业的话其实还算轻松，因为大部分零件可以自制，只需要肝些以太结晶。花是正篇最强异刃，除非只求通关剧情，否则绕不过去。","kind":"tip","title":"花的制作书 3"},{"text":"② 真诚大厅左边往下的路，通过场景技能开门后可以到达**洛修利亚[[地标:圣遗物宝物库]]**，里面有几个不错的宝箱。","kind":"tip","title":null},{"text":"③ 跟洛修利亚的卫兵战斗有概率掉落 [[物品:慈爱项饰◆◆◆]]（回血量增加），可以先给尼娅过渡用。","kind":"tip","title":null},{"text":"④ [[地标:洛修利亚王都]]的旅店有个地标记得开启，常用地标。","kind":"tip","title":null},{"text":"⑤ 洛修利亚后门・特奥斯皮斯缇神殿遗迹处有个可用场景技能破坏的石壁，里面有个可以供奉的祭坛，**供奉满后可以获得稀有异刃「天威」**。天威是原输出三巨头之一，以当前版本看有些过时，但那是相对各种 DLC 异刃与最终 BOSS 战后才能抽的异刃而言，以当前进度客观说还是很强。刷供奉材料一般去英维迪亚烈头部・[[地标:下颚漂流地]]第 3 章开头水池边上那几个采集点。","kind":"tip","title":"稀有异刃：天威"}]},{"title":"回到利贝拉里塔斯岛屿群，在[[地标:弥先村]]拱门附近打听爷爷的事","body":"","notes":[]},{"title":"沿着从守护神出现的通道往下，前往[[地标:艾尔皮斯灵洞]]","body":"这里是整个游戏中最复杂的迷宫。焰不在战力差很多，而且灵洞会限制花以外异刃的必杀等级，难以达成异刃连击，我方输出大打折扣，因此**尽量避免和野怪战斗**。拉比亚地下水流处直接从水流中滑下去更快。","notes":[]},{"title":"探索[[地标:艾尔皮斯灵洞]]的下层（中层路线）","body":"进入中层后，必杀技只能攒一段。中层地图复杂度急剧上升，第一关就是三层结构：入口处于一层，经过南边的螺旋回廊绕一圈后到达二层；从回廊出来面前就有一个斜坡，走上去会塌方掉至一层；正确路线是**右转尽头一个不起眼的洞口**，再次进入螺旋回廊到达三层。","notes":[{"text":"[[异刃:绵津见]]的核心水晶最晚在这里也差不多可以调谐了，给梅勒芙调谐吧。","kind":"tip","title":null},{"text":"经过布满蜘蛛网的洞窟，进入最难的第二关**[[地标:艾尔皮斯大空洞]]**：纵深极高，目的地是入口下方 150 的平台，里面有海胆怪、羽蛇等非常难对付的敌人，碰上很容易团灭，还有不少需要高等级场景技能的机关。","kind":"warn","title":"艾尔皮斯大空洞"},{"text":"捷径（第一次来很难发现）：①在大空洞入口处把视角转 180°，笔直朝下，屏幕右下角有个位于入口正下方的平台，第一步跳上此平台；②跳到左边的平台上；③跳上墙壁上延伸出来的断桥；④跳到下面的另一个断桥（也可以往前跳顺路拿个宝箱，内有一片[[物品:顽火辉石晶片]]，值得一拿，建议用来强化[[异刃:迦具土]]，她是接下来剧情战斗的主力）；⑤从那里落到下一层平台，高度刚好不会摔死；⑥到达目的地。","kind":"tip","title":"大空洞捷径"}]},{"title":"向[[地标:艾尔皮斯灵洞]]的最深处进发","body":"来到侵蚀灰洞，左边的路需要「焚烧殆尽」（火属性之力 Lv3 + 风属性之力 Lv4），还是走右边比较好。来到[[地标:奉纳大厅]]先存档：这个场景中间有许多小蜘蛛，避免引战，因为前面需要发动场景技能，旁边还有只大稀有怪蜘蛛。使用「焚烧殆尽」（火属性之力 Lv3 + 风属性之力 Lv2）破坏蜘蛛网，来到最下层[[地标:审判石碑]]。","notes":[{"text":"此处需要场景技能「远古解读」（观察眼 Lv2 + 古代文明的知识 Lv3）。剧情中必定获得的异刃里，[[异刃:迦具土]]拥有观察眼，白虎和[[异刃:绵津见]]拥有古代文明的知识。","kind":"tip","title":null},{"text":"备注补充：[[地标:奉纳大厅]]上的蜘蛛网要**选粗的走**，细的走上去会掉落到下面，虽然问题不大，但上面的宝箱想拿又得绕一大圈。","kind":"tip","title":null}]},{"title":"打倒盘踞在[[地标:艾尔皮斯灵洞]]最深处的幻影等敌人 0/4","body":"战斗：Lv44 幻影。","notes":[{"text":"幻影本身不强，但每个幻影打到 25% 时会使用暗影分身，招出两个新幻影。效率的打法是后开连锁一起杀死，但攻击力不够高的话没连死就很尴尬。","kind":"tip","title":"幻影战"},{"text":"建议玩家控制梅勒芙的[[异刃:迦具土]]：[[异刃:迦具土]]有回避攻击后攻击力提升的被动技能，最多提升 250%（即 3.5 倍），一级必杀又是自身周围 AOE，使她在本战中极为强大——前面拿到的武器晶片就是为这里准备的。攒满队伍槽后引导敌人聚在[[异刃:迦具土]]周围（注意不要有正在分身的敌人），开启连锁：连锁初始就有 300% 多的威力加成，再加上回避增加的攻击力，1 级必杀每段都有上万伤害。其实幻影也不是无限分身，总共打掉大约 25 个就算胜利，慢慢杀也能过。","kind":"tip","title":null}]},{"title":"暂时回到[[地标:弥先村]]商量今后的打算","body":"系统更新：可将尼娅作为异刃使用。","notes":[]},{"title":"找斯佩比亚哈达夏尔军港的索弗拉对话，前往[[地标:莫尔斯断崖]]","body":"[[地标:莫尔斯断崖]]也是多层复式结构，敌人强度很高，最深处还有一场难度很高的战斗。沿路会用到风属性之力 Lv3、地属性之力 Lv3、跳跃 Lv3，做好准备。","notes":[{"text":"支线解锁：「[[任务:莫尔斯的特产]]」。","kind":"tip","title":null},{"text":"备注补充：[[地标:莫尔斯断崖]]入海口前边的悬崖边上有只 53 级精英 BOSS「[[敌人:机关枪的皮特]]」（飞在悬崖边的大鸟），记住它，很多稀有异刃技能激活都需要打它。","kind":"tip","title":null},{"text":"备注补充：[[地标:巴尔克鲁斯遗迹]]在与灭战斗后地上会形成一个塌陷洞，这地方涉及诺彭十二兄弟的任务；该遗迹处还可以新增一个打捞点，需要返回虎的家领取支线任务，领取后在此打捞可以确认新的打捞点（原来没有的）。","kind":"tip","title":null},{"text":"备注补充：[[地标:莫尔斯断崖]]那些飞在悬崖边的怪物（包括精英 BOSS）可以利用素质四连中的**倒地**做地形杀——只要出了倒地就会摔下悬崖死掉（明明会飞的）。[[地标:圣年之门]]里面有开门的机关，第一次从山上跳到门内后记得开一下门。[[地标:圣年之门]]门外的山道悬崖边上有只 58 级精英 BOSS「[[敌人:绯红色的隆基凯普斯]]」，包括焰在内的多个稀有异刃技能激活也会需要你去打它。","kind":"tip","title":null},{"text":"备注补充：[[地标:圣年之门]]打捞点有概率打捞出大章鱼，会有概率掉落 [[物品:贝塔瞄准镜◆◆]]（最早入手的点），这是非常重要的素质四连装备，必刷。刷法：普通气瓶、按键挑战全部故意按错（增加出怪概率）；捞出来的不是章鱼就直接用倒地拉下悬崖，如果是章鱼需要引到[[地标:圣年之门]]内部位置击杀，否则捡不到东西。","kind":"tip","title":"必刷：[[物品:贝塔瞄准镜◆◆]]"}]},{"title":"打倒灭 0/1","body":"战斗：Lv52 灭（第七章第一战）。完全体的灭，此战难度非常高。","notes":[{"text":"灭的技能：突袭斩击（出招极快的单体斩击，击退效果，背面伤害翻倍）、莫纳德旋风（轟，带吹飞的 AOE）、莫纳德囚禁（封，异刃封锁无法切换异刃）、莫纳德装甲（鎧，异刃连击缩短 + 90% 减伤）、莫纳德吞噬（喰，异刃牵绊降低）、莫纳德爆发（斬，前方直线高伤害 AOE）。","kind":"warn","title":"灭的技能表"},{"text":"最烦人的是莫纳德吞噬带来的牵绊降低，相当于给我方上了一个超强 debuff，而封印此效果需要光属性异刃连击——除非运气好抽到 KOS-MOS，不然只能顶着打。灭的攻击伤害也很高，回复压力巨大；半血愤怒后技能释放间隔明显加快，我方难以招架。伤害最高的莫纳德爆发是愤怒后才会使用，看到愤怒后尽快开连锁，2 球连锁大概能打一半血。","kind":"tip","title":null}]},{"title":"赶往[[地标:莫尔斯断崖]]的最深处","body":"到达[[地标:圣年之门]]时门关着，走边上的小路往上爬，来到秘境**修道者古道**，此处需要场景技能「踩墙跳」（地属性之力 Lv2 + 跳跃 Lv3）。这里有堪称全游戏最强冠名者的「[[敌人:樱花一刀流]]」，当然不用和他打；从他面前的平台跳下，一路往下跳，跳到[[地标:圣年之门]]上面翻过去。","notes":[]},{"title":"打倒真和灭，夺回焰与光 0/2","body":"战斗：Lv54 真、Lv56 灭。","notes":[{"text":"真和灭一起上，难度更大，好在只要将其中一人 HP 打到 50% 就会触发剧情。真的 HP 较低但敏捷高、无敌回避技能多，反而还是打灭比较容易。真会使用挑衅，时刻注意攻击目标，切换回去的时候记得按一下集中攻击。","kind":"tip","title":null}]}],"diffs":[{"src":"《每章更多备注》","text":"备注对第七章的定位是「中后期最后一段可以肝的自由时间」：开启洛修利亚王国后，这张图有不少准毕业及毕业级装备可以刷，大部分稀有异刃的支线任务也都能做了，是主角团逐渐成型的阶段。"},{"src":"《每章更多备注》","text":"备注还给了两条与本章地点相关的长线收益：其一，**[[地标:遗迹沉睡之岛]] / [[地标:神渡之岛]] / 空中宝座**等群岛与洛修利亚秘境涉及大量支线与异刃技能激活怪，建议列成清单逐个清；其二，**空中宝座**是前往[[地标:封闭矿石厂]]最近的地标，而[[地标:封闭矿石厂]]是[[物品:迷恋药]]主材料「心跳蓟」的采集点，[[物品:迷恋药]]又是中后期最省力的开环手段。"}],"quests":["巴恩的秘密财产！？","壁画之谜","汇款流程","过去的光辉","好搭档","莫尔斯的特产"],"images":[{"src":"assets/mag/vol2-p024.webp","alt":"下册 第 24 页：第 7 章：弥先岛与守护神地标","caption":"第 7 章：弥先岛与守护神地标","src_ref":"原刊：下册 第 24 页（《掌机王Plus 异度神剑2 攻略特辑》）","link":"#/mag/vol2-024"},{"src":"assets/mag/vol2-p025.webp","alt":"下册 第 25 页：第 7 章 BOSS：幻影 / Lv52 灭","caption":"第 7 章 BOSS：幻影 / Lv52 灭","src_ref":"原刊：下册 第 25 页（《掌机王Plus 异度神剑2 攻略特辑》）","link":"#/mag/vol2-025"},{"src":"assets/mag/vol1-p020.webp","alt":"上册 第 20 页：支线：离别赠礼","caption":"支线：离别赠礼","src_ref":"原刊：上册 第 20 页（《掌机王Plus 异度神剑2 攻略特辑》）","link":"#/mag/vol1-020"},{"src":"assets/mag/vol1-p025.webp","alt":"上册 第 25 页：异刃任务：洛修利亚崩城","caption":"异刃任务：洛修利亚崩城","src_ref":"原刊：上册 第 25 页（《掌机王Plus 异度神剑2 攻略特辑》）","link":"#/mag/vol1-025"}]},{"id":"ch8","num":"第八章","title":"世界树","short":"世界树","badge":"8","color":"cc-bg8","summary":"世界树篇：全员离队到重新集结，觉醒圣杯登场，战斗系统至此完全解锁。","place":["莫尔斯之地","世界树"],"keypoints":[{"text":"第八章是「憋屈—解放」的一章：前半莱克斯几乎单人行动，后半全员归队、[[异刃:觉醒圣杯]]上线，可以开始把之前积压的养成一次做完。","kind":"tip","title":"本章节奏"},{"text":"进[[地标:世界树]]后到天空桥剧情将**无法再返回阿卡狄亚**：支线「[[任务:圣歌队的梅丽卡]]」「[[任务:阿卡狄亚的教义]]」会无法完成，「[[任务:追求新天地]]」会无法接取。想全收集的话，请在天空桥剧情前把阿卡狄亚的宝箱、佣兵团任务和时叶的善行事件都处理掉。","kind":"warn","title":"不可逆节点"}],"steps":[{"title":"边查找坠落至[[地标:莫尔斯之地]]的同伴，边向[[地标:世界树]]的根部进发","body":"莱克斯以外全员离队。","notes":[{"text":"系统更新：TIGER! TIGER! 追加新关卡、奖品更新；莱克斯可使用全部异刃。支线解锁：「[[任务:双亲之仇]]」「[[任务:打捞员之王]]」「[[任务:持续运转的系统]]」。至此整个战斗系统完全解锁。","kind":"tip","title":null},{"text":"[[异刃:觉醒圣杯]]的能力极为强悍，之后战斗多加利用，会大幅降低难度。","kind":"tip","title":null}]},{"title":"探索[[地标:莫尔斯之地]]，前往传出战斗声响的地方","body":"打倒死亡恐惧异形怪 0/1（Lv52）。真临时入队，他单人就能打全一整套四连，赶紧体验下。","notes":[]},{"title":"继续寻找同伴，向[[地标:世界树]]的根部进发","body":"[[异刃:迦具土]]入队，莱克斯的 3 号异刃位自动配置了[[异刃:迦具土]]。打倒地狱之血异形怪 0/8（Lv50 ×3、Lv51 ×3、Lv52 ×2）。","notes":[{"text":"跟真相比莱克斯非常脆皮，尽量让真吸引仇恨，攒满队伍槽就开小绿放必杀清屏。","kind":"tip","title":null}]},{"title":"探索坠落至[[地标:莫尔斯之地]]的伊拉巨神兽胎中中枢","body":"这里的敌人非常强，我方两人战力明显不足，建议操作防御高的真直接冲过去。**建议在最后存个档**，因为下面那场战斗万一输了，再想赢就非常难。","notes":[]},{"title":"打倒恶魔之王异形怪 0/1","body":"战斗：Lv60 恶魔之王异形怪。开战直接发动觉醒，打到 80% 发生剧情，全员归队。","notes":[{"text":"Boss 挺弱，麻烦的是它的拍地和光束都是范围伤害，而队友 AI 很弱智，一直跟坦克站一起，直到躺了也不会移动。所以最好是玩家操作坦克位置，主动远离队友。","kind":"tip","title":null},{"text":"血量很多（200 多万），但有[[异刃:觉醒圣杯]]完全不在话下：觉醒状态进入连锁，每次必杀都会对所有属性球造成伤害，4 球可以稳定发动 Full Combo，保底也能打 100 多万。因为觉醒状态每场战斗只能发动一次且有时间限制，所以最好先攒几个球再进觉醒状态。","kind":"tip","title":null},{"text":"技能：元素光束（正面直线 AOE）、元素复制（单体高伤害并复制目标属性）、元素毒气（根据当前属性给我方附加状态）、茁壮成长（60% 左右发动，召唤 3 个小怪，小怪时间久了也会使用元素爆弹）、元素爆弹（全屏一万多伤害，可用封印自爆免疫，后期才会使用，一般见不到）。","kind":"tip","title":null}]},{"title":"前往[[地标:世界树]]的根部","body":"","notes":[{"text":"支线解锁：「[[任务:花的魔改造]]」。","kind":"tip","title":null},{"text":"莱克斯解锁了主控御刃者能力，可以任意绑定其他人的异刃，属性和连击搭配自由度大了许多。如果之前没抽到好的斧头，可以让莱克斯绑定彩歌打浮空、朱雀打猛击，让队友专注破防，这样一套御刃者连击 build 就成型了，队伍输出会大幅提高。","kind":"tip","title":null}]},{"title":"从[[地标:莫尔斯之地]]・大浮标底部乘坐[[地标:世界树]]的升降机，登上[[地标:世界树]]","body":"进入[[地标:世界树]]。","notes":[{"text":"到天空桥剧情后**无法返回阿卡狄亚**：支线「[[任务:圣歌队的梅丽卡]]」「[[任务:阿卡狄亚的教义]]」将无法完成；「[[任务:追求新天地]]」将无法接取；还有时叶的善行事件（特殊事件「小小的善行」，其中「扔硬币」很方便完成），如果善行事件还没做满 3 个，不要错过。","kind":"warn","title":"不可逆节点"},{"text":"如果追求全收集，不要忘了打开阿卡狄亚教廷的所有宝箱、解锁并做完阿卡狄亚的佣兵团任务（不需要解锁七冰的佣兵团任务，之后到群岛还能解锁），以及萤的偷心事件（奥丽艾塔）。","kind":"tip","title":null}]},{"title":"探索[[地标:世界树]]（两个机关）","body":"[[地标:世界树]]的场景比较简单，下层主要两个机关：①第二层水星天，去下面的控制室操作面板放掉废弃物处理室的水；②天空桥三岔路先去上面的数据管理室拿「信息代码」（这里的幻象机甲非常厉害，多存档），然后开启右下角电梯的门。坐电梯后一路敌人非常多，不过前面就是主线剧情发生点，可以控制坦克冲过去跳过这一群敌人。","notes":[]},{"title":"击退阿卡狄亚军 0/6","body":"战斗：Lv57 阿卡狄亚护卫兵 ×5、Lv60 阿卡狄亚煌星。","notes":[]}],"diffs":[{"src":"《每章更多备注》","text":"备注给第八章的态度是「不要停留」：进入第 8 章标志游戏彻底进入后期，绝大多数稀有异刃都可以把牵绊圆环开满（极个别需要上乐园）。如果第 6、7 章已经肝过异刃和支线，就不建议在这里停太久，拿完重要东西、做完重要支线就把主线推到乐园——只有主线进度到乐园，所有任务与珍稀种 BOSS 才会彻底开放，与其半吊子不如先享受剧情，上乐园后再肝一波。"},{"src":"《每章更多备注》","text":"备注对尼娅的定位有明确建议：尼娅作为异刃时生存能力很强但输出不高，推荐仍作为御刃者使用，定位主输出 + 副奶妈。理由是后期很多精英 BOSS 有秒人技能，输出上不去就无法速杀，靠奶是奶不回来的；奶的主要作用是对 BOSS 平 A 与非秒人技能的伤害做回复。如果异刃与装备毕业、能玩融合连击 + 闪避流，不带奶也没问题。"}],"quests":["双亲之仇","打捞员之王","持续运转的系统","花的魔改造"],"images":[{"src":"assets/mag/vol2-p026.webp","alt":"下册 第 26 页：第 8 章：莫尔斯之地世界树 / 巨大防壁第八隧道","caption":"第 8 章：莫尔斯之地世界树 / 巨大防壁第八隧道","src_ref":"原刊：下册 第 26 页（《掌机王Plus 异度神剑2 攻略特辑》）","link":"#/mag/vol2-026"},{"src":"assets/mag/vol2-p027.webp","alt":"下册 第 27 页：第 8 章：封印增援与放射性废弃物处理室","caption":"第 8 章：封印增援与放射性废弃物处理室","src_ref":"原刊：下册 第 27 页（《掌机王Plus 异度神剑2 攻略特辑》）","link":"#/mag/vol2-027"}]},{"id":"ch9","num":"第九章","title":"雨","short":"雨","badge":"9","color":"cc-bg1","summary":"世界树高层：连续的 BOSS 战，真与神铠麦佩尼是主线里最考验配置的两场战斗。","place":["世界树","第七外围机场","阿卡狄亚"],"keypoints":[{"text":"本章几乎没有探索内容，全是战斗与剧情，重点是**换好配置再上**：真需要续航与必中必杀连锁，麦佩尼需要血上限与减员容错。","kind":"warn","title":"本章重点"}],"steps":[{"title":"追逐真和灭，并登上[[地标:世界树]]","body":"","notes":[{"text":"支线解锁：「[[任务:冻成冰块的御刃者]]」「离别赠礼」。","kind":"tip","title":null}]},{"title":"从[[地标:世界树]]的[[地标:第七外围机场]]顶端靠近阿卡狄亚的巨神兽","body":"到达[[地标:第七外围机场]]，这里离剧情点非常长，路上敌人非常多，步步为营。","notes":[]},{"title":"追逐真和灭并登上[[地标:世界树]]，阻止弑神","body":"","notes":[{"text":"支线解锁：「[[任务:在世界树遇难]]」。","kind":"tip","title":null},{"text":"驱动控制面板需要「力量全开」（雷属性之力 Lv4 + 集中力 Lv5），集中力要求比较高，最简单的方法是焰 Lv2 + 光 Lv2 + 力男 Lv1；光焰的集中力牵绊环吃几个东西就能解。进去之后发现电梯前有机甲挡路，从左边的阶梯蹭过去即可。","kind":"tip","title":null},{"text":"支线解锁：「[[任务:协助煮饭]]」。","kind":"tip","title":null}]},{"title":"和真一决胜负","body":"战斗：Lv66 真。","notes":[{"text":"比之前多了一个技能「零圈」：全场回复无效，经常接在刹那后面，导致全团血线非常危险；「天乱剑」出手也是毫无理由地秒人，愤怒后会使用大杀招「无刃剑」，基本见不到。","kind":"warn","title":"真（第九章）"},{"text":"真的基础数值属于贫血高敏捷类型，比他敏捷高的敌人都是 99 级以上的珍稀种，因此主要输出还是靠必中的必杀连锁，一般 2 球就够。此战血线压力大、容易减员，拉人会导致团队槽经常不够放连锁，可以佩戴「[[物品:再生标志]]」解决这个问题（如果有的话）。","kind":"tip","title":null}]},{"title":"和麦佩尼一决胜负","body":"战斗：Lv68 神铠麦佩尼。","notes":[{"text":"技能：神圣法袍（随机切换自身属性）、罪恶法杖（前方范围伤害带吹飞）、万千触手（全体伤害，0 抗性时约 3000）、统治（异刃封锁）、神圣之箭（对当前目标的小范围超高伤害 AOE）、神之暴怒（半血愤怒使用，短时间无敌，结束带浮空）、福音之光（吸收所有伤害并回复约八分之一 HP）。","kind":"warn","title":"麦佩尼技能表"},{"text":"教皇最大的威胁是高频率的万千触手，建议给血少的佩戴增加 HP 上限的饰品，能大幅增加存活率。神圣之箭属于出了就秒人的技能，只能祈祷它 MISS；Boss 的单体普攻伤害也很高，外加使用频率很高的罪恶法杖，一旦 OT 也很容易减员。","kind":"tip","title":null},{"text":"觉得难打可以上**双坦克阵容**，主角带尼娅主回复，就算一个坦克被秒也不会崩盘；2 个球之后开[[异刃:觉醒圣杯]]上第三套异刃连击，3 球连锁足以打掉他三分之二血。","kind":"tip","title":null}]}],"diffs":[{"src":"《每章更多备注》","text":"备注在这里补了「尼亚的异刃形态」的取舍：作为异刃生存力强但输出低，仍推荐当御刃者用（主输出 + 副奶妈）。理由是后期精英 BOSS 普遍带秒人技能，输出不足就无法速杀，奶量并不能真正解决问题。"}],"quests":["冻成冰块的御刃者","离别赠礼","在世界树遇难","协助煮饭"],"images":[{"src":"assets/mag/vol2-p028.webp","alt":"下册 第 28 页：最终章：第一低轨道站地图 / 老旧教会","caption":"最终章：第一低轨道站地图 / 老旧教会","src_ref":"原刊：下册 第 28 页（《掌机王Plus 异度神剑2 攻略特辑》）","link":"#/mag/vol2-028"}]},{"id":"final","num":"最终章","title":"于是 少年遇到了少女","short":"于是 少年遇到了少女","badge":"终","color":"cc-bg2","summary":"乐园篇：连续的单挑与最终 BOSS 永劫装置，注意战前配置与两次觉醒圣杯的使用。","place":["乐园","第一低轨道站","永劫机库"],"keypoints":[{"text":"教会地下剧情后光焰与所有队友会临时离队，莱克斯将与队友依次单挑；**离队后无法绑定离队时队友绑定的异刃**，请提前准备好应战配置，建议多带回复异刃。","kind":"warn","title":"开战前务必换装"},{"text":"最终 BOSS 分两场，Boss 打到 70% 锁血发生剧情，意味着**可以使用两次[[异刃:觉醒圣杯]]**。","kind":"tip","title":null}],"steps":[{"title":"乘坐太阳天第 1 电梯，向乐园前进","body":"","notes":[{"text":"支线解锁：「[[任务:集合吧！诺彭币]]」「[[任务:巴恩的报复]]」「[[任务:考尔的病]]」「学校」。","kind":"tip","title":null}]},{"title":"穿过拉达曼迪斯入口，向乐园进发","body":"","notes":[]},{"title":"前往传来声响方向的大型建筑物确认真相","body":"","notes":[]},{"title":"前往教会地下寻找发出声响之人","body":"教会地下剧情后，光焰和所有队友临时离队，莱克斯将与每个队友依次战斗。","notes":[{"text":"**注意**：离队后莱克斯无法绑定离队时队友绑定的异刃，请提前准备好应战配置，建议多带回复异刃，不然很难打。","kind":"warn","title":null}]},{"title":"阻止尼娅 0/1","body":"战斗：尼娅。","notes":[]},{"title":"阻止梅勒芙 0/1","body":"战斗：梅勒芙。","notes":[]},{"title":"阻止虎和齐格 0/2","body":"战斗：虎、齐格。","notes":[]},{"title":"赶往第一低轨道站的最深处永劫机库","body":"全员归队，前往最深处迎战最终 Boss 永劫装置。战斗：Lv70 永劫装置。","notes":[{"text":"技能：暴雪（全体伤害，附加破防和回复无效）、人类（异刃牵绊降低 + 异刃封锁）、X 星（全体伤害）、奴役战争（分别在 85%、50%、30% 发动一次，召唤泰坦装置）、塞壬暴击（全体极大伤害）、火焰齿轮（使用时无敌，结束后进入愤怒状态）、普罗米修斯（20% 以下使用，全屏 30000 左右伤害）。","kind":"warn","title":"永劫装置技能表"},{"text":"永劫没有单体攻击，普攻也是全体伤害，所以这一战其实可以不上坦克，坦克唯一的作用就是拉住中途召唤出来的泰坦装置。","kind":"tip","title":null},{"text":"**第一场**：85% 发动奴役战争，Boss 会退到很远的地方，还要打一个泰坦装置，很浪费时间——直接 2 球连锁打到 70% 跳过该技能阶段。","kind":"tip","title":"第一场"},{"text":"**第二场**：开场必定飞远来一发塞壬暴击，初见没做准备很容易全员扑街。把以太抗性高的异刃放首位、再堆血量和以太抗性是可以硬扛的，但没有必要——第二场战斗开始时队伍槽直接是满的，利用连锁攻击的无敌时间跳过塞壬暴击即可。开连锁的具体时机是永劫的左手抬起来遮住脸时。","kind":"warn","title":"第二场"},{"text":"永劫在 50%、30% 各使用一次奴役战争，并且在使用奴役战争后的约 2 分 20 秒必定发动塞壬暴击。20% 以下有机会见到全游戏最炫也最强的敌方技能「普罗米修斯」。","kind":"tip","title":null}]}],"diffs":[{"src":"《每章更多备注》","text":"备注说明：主线进度到乐园后，这个游戏所有的任务和珍稀种 BOSS 才会彻底对你开放，所以之前积压的养成内容可以在通关前后集中处理。"}],"quests":["集合吧！诺彭币","巴恩的报复","考尔的病","学校"],"images":[{"src":"assets/mag/vol2-p028.webp","alt":"下册 第 28 页：最终章：第一低轨道站地图 / 老旧教会","caption":"最终章：第一低轨道站地图 / 老旧教会","src_ref":"原刊：下册 第 28 页（《掌机王Plus 异度神剑2 攻略特辑》）","link":"#/mag/vol2-028"}]}];
